window.ETEXTBOOK={"units": [{"id": "u1", "title": "传统教育的发展", "sections": [{"id": "u1_s1", "title": "第4章 教育（Education）", "paras": []}, {"id": "u1_s2", "title": "导入问题", "paras": [{"id": "u1_s2_p1", "buf": ["• Do you know what the four great classical academies (四大书院) in ancient China were?"], "text": "• Do you know what the four great classical academies (四大书院) in ancient China were?", "chunks": ["• Do you know what the four great classical academies (四大书院) in ancient China were?"]}, {"id": "u1_s2_p2", "buf": ["• Can you name the Four Books and the Five Classics (“四书五经”)?"], "text": "• Can you name the Four Books and the Five Classics (“四书五经”)?", "chunks": ["• Can you name the Four Books and the Five Classics (“四书五经”)?"]}, {"id": "u1_s2_p3", "buf": ["• Do you know when the imperial civil examination system began and when it was abolished?"], "text": "• Do you know when the imperial civil examination system began and when it was abolished?", "chunks": ["• Do you know when the imperial civil examination system began and when it was abolished?"]}, {"id": "u1_s2_p4", "buf": ["• Do you know of any public welfare projects that help children in disadvantaged areas of China?"], "text": "• Do you know of any public welfare projects that help children in disadvantaged areas of China?", "chunks": ["• Do you know of any public welfare projects that help children in disadvantaged areas of China?"]}]}, {"id": "u1_s3", "title": "传统教育的发展", "paras": [{"id": "u1_s3_p1", "buf": ["Since ancient times, education and scholarship have been highly valued in China. The country accumulated extensive experience in establishing both private and official schools, creating educational networks based on administrative divisions, and promoting multi-channel, multi-level approaches to learning. Ancient China implemented systems such as the imperial civil examination system and the academy system. These practices not only placed China among the most advanced educational societies but also featured many unique characteristics in both content and form."], "text": "Since ancient times, education and scholarship have been highly valued in China. The country accumulated extensive experience in establishing both private and official schools, creating educational networks based on administrative divisions, and promoting multi-channel, multi-level approaches to learning. Ancient China implemented systems such as the imperial civil examination system and the academy system. These practices not only placed China among the most advanced educational societies but also featured many unique characteristics in both content and form.", "chunks": ["Since ancient times, education and scholarship have been highly valued in China. The country accumulated extensive experience in establishing both private and official schools, creating educational networks based on administrative divisions, and promoting multi-channel, multi-level approaches to learning. Ancient China implemented systems such as the imperial civil examination system and the academy system. These practices not only placed China among the most advanced educational societies but also featured many unique characteristics in both content and form."]}]}, {"id": "u1_s4", "title": "私学", "paras": [{"id": "u1_s4_p1", "buf": ["A sishu (私塾) was a type of private educational institution in ancient China, typically established within families or villages to provide early childhood education. These privately run schools formed an important part of the traditional private education system."], "text": "A sishu (私塾) was a type of private educational institution in ancient China, typically established within families or villages to provide early childhood education. These privately run schools formed an important part of the traditional private education system.", "chunks": ["A sishu (私塾) was a type of private educational institution in ancient China, typically established within families or villages to provide early childhood education. These privately run schools formed an important part of the traditional private education system."]}, {"id": "u1_s4_p2", "buf": ["During the Spring and Autumn Period, private schools began to emerge, and many scholars of different schools of thought spread their teachings through private instruction. Among them, Confucius’s private teaching was the most influential and far-reaching. Confucius devoted his entire life to education and instructed many students. It is said that over 3,000 disciples followed him, of whom 72 were especially distinguished and went on to spread Confucian philosophy."], "text": "During the Spring and Autumn Period, private schools began to emerge, and many scholars of different schools of thought spread their teachings through private instruction. Among them, Confucius’s private teaching was the most influential and far-reaching. Confucius devoted his entire life to education and instructed many students. It is said that over 3,000 disciples followed him, of whom 72 were especially distinguished and went on to spread Confucian philosophy.", "chunks": ["During the Spring and Autumn Period, private schools began to emerge, and many scholars of different schools of thought spread their teachings through private instruction. Among them, Confucius’s private teaching was the most influential and far-reaching. Confucius devoted his entire life to education and instructed many students. It is said that over 3,000 disciples followed him, of whom 72 were especially distinguished and went on to spread Confucian philosophy."]}, {"id": "u1_s4_p3", "buf": ["Thoughts of other schools, such as Daoism, were also widely taught, contributing to “the contention of a hundred schools of thought”. Throughout many dynasties, private schools flourished alongside official schools."], "text": "Thoughts of other schools, such as Daoism, were also widely taught, contributing to “the contention of a hundred schools of thought”. Throughout many dynasties, private schools flourished alongside official schools.", "chunks": ["Thoughts of other schools, such as Daoism, were also widely taught, contributing to “the contention of a hundred schools of thought”. Throughout many dynasties, private schools flourished alongside official schools."]}]}, {"id": "u1_s5", "title": "官学", "paras": [{"id": "u1_s5_p1", "buf": ["During the Western Zhou Dynasty, official schools flourished. These schools primarily admitted children of the nobility. The official schooling system included a central school and local schools in different administrative regions. The teaching materials focused on classical texts such as the Four Books and the Five Classics. After the Sui and Tang dynasties, official schools began to impose certain restrictions on students’ age and duration of study, allowing a small number of students to be appointed as officials upon completing the required period of study. However, for the majority of scholars, the imperial civil examination remained the essential path to entering officialdom."], "text": "During the Western Zhou Dynasty, official schools flourished. These schools primarily admitted children of the nobility. The official schooling system included a central school and local schools in different administrative regions. The teaching materials focused on classical texts such as the Four Books and the Five Classics. After the Sui and Tang dynasties, official schools began to impose certain restrictions on students’ age and duration of study, allowing a small number of students to be appointed as officials upon completing the required period of study. However, for the majority of scholars, the imperial civil examination remained the essential path to entering officialdom.", "chunks": ["During the Western Zhou Dynasty, official schools flourished. These schools primarily admitted children of the nobility. The official schooling system included a central school and local schools in different administrative regions. The teaching materials focused on classical texts such as the Four Books and the Five Classics. After the Sui and Tang dynasties, official schools began to impose certain restrictions on students’ age and duration of study, allowing a small number of students to be appointed as officials upon completing the required period of study. However, for the majority of scholars, the imperial civil examination remained the essential path to entering officialdom."]}, {"id": "u1_s5_p2", "buf": ["the Four Books and the Five Classics: The term “Four Books” refers to the four Confucian classics: The Great Learning, The Doctrine of the Mean, The Analects, and Mencius. The term “Five Classics” refers to the five Confucian classics: The Book of Songs, The Book of History, The Book of Rites, The Book of Changes, and The Spring and Autumn Annals. “四书”是《大学》《中庸》《论语》《孟子》四部儒家经典的合称；“五经”是《诗》《书》《礼》《易》《春秋》五部儒家经典的合称。"], "text": "the Four Books and the Five Classics: The term “Four Books” refers to the four Confucian classics: The Great Learning, The Doctrine of the Mean, The Analects, and Mencius. The term “Five Classics” refers to the five Confucian classics: The Book of Songs, The Book of History, The Book of Rites, The Book of Changes, and The Spring and Autumn Annals. “四书”是《大学》《中庸》《论语》《孟子》四部儒家经典的合称；“五经”是《诗》《书》《礼》《易》《春秋》五部儒家经典的合称。", "chunks": ["the Four Books and the Five Classics: The term “Four Books” refers to the four Confucian classics: The Great Learning, The Doctrine of the Mean, The Analects, and Mencius. The term “Five Classics” refers to the five Confucian classics: The Book of Songs, The Book of History, The Book of Rites, The Book of Changes, and The Spring and Autumn Annals. “四书”是《大学》《中庸》《论语》《孟子》四部儒家经典的合称；“五经”是《诗》《书》《礼》《易》《春秋》五部儒家经典的合称。"]}]}, {"id": "u1_s6", "title": "书院", "paras": [{"id": "u1_s6_p1", "buf": ["Classical academies came into being during the Tang Dynasty and continued until the end of the Qing Dynasty. They were established in various localities for teaching, research, and book collection. Independent of official schools, they were often located in tranquil and picturesque settings, fostering academic freedom and innovation and emphasising character development. Academies had a profound impact on the development of education and culture in ancient China, and played a significant role in promoting Chinese culture abroad."], "text": "Classical academies came into being during the Tang Dynasty and continued until the end of the Qing Dynasty. They were established in various localities for teaching, research, and book collection. Independent of official schools, they were often located in tranquil and picturesque settings, fostering academic freedom and innovation and emphasising character development. Academies had a profound impact on the development of education and culture in ancient China, and played a significant role in promoting Chinese culture abroad.", "chunks": ["Classical academies came into being during the Tang Dynasty and continued until the end of the Qing Dynasty. They were established in various localities for teaching, research, and book collection. Independent of official schools, they were often located in tranquil and picturesque settings, fostering academic freedom and innovation and emphasising character development. Academies had a profound impact on the development of education and culture in ancient China, and played a significant role in promoting Chinese culture abroad."]}, {"id": "u1_s6_p2", "buf": ["When the imperial civil examination system was abolished, most of the academies were converted into schools,"], "text": "When the imperial civil examination system was abolished, most of the academies were converted into schools,", "chunks": ["When the imperial civil examination system was abolished, most of the academies were converted into schools,"]}, {"id": "u1_s6_p3", "buf": ["There were four famous academies in ancient China: Yuelu Academy in Changsha, Hunan Province; Bailudong Academy in Jiujiang, Jiangxi Province; Songyang Academy in Zhengzhou, Henan Province; and Yingtian Academy in Shangqiu, Henan Province."], "text": "There were four famous academies in ancient China: Yuelu Academy in Changsha, Hunan Province; Bailudong Academy in Jiujiang, Jiangxi Province; Songyang Academy in Zhengzhou, Henan Province; and Yingtian Academy in Shangqiu, Henan Province.", "chunks": ["There were four famous academies in ancient China: Yuelu Academy in Changsha, Hunan Province; Bailudong Academy in Jiujiang, Jiangxi Province; Songyang Academy in Zhengzhou, Henan Province; and Yingtian Academy in Shangqiu, Henan Province."]}]}, {"id": "u1_s7", "title": "科举制度", "paras": [{"id": "u1_s7_p1", "buf": ["The imperial civil examination system dominated education in China’s feudal society. It became the primary method through which talented individuals were recognised and appointed as government officials. The practice began in the Sui Dynasty and lasted for about 1,300 years, until the end of the Qing Dynasty. It had a profound impact on the social structure, political system, educational system, and humanistic ideologies of China after the Sui and Tang dynasties."], "text": "The imperial civil examination system dominated education in China’s feudal society. It became the primary method through which talented individuals were recognised and appointed as government officials. The practice began in the Sui Dynasty and lasted for about 1,300 years, until the end of the Qing Dynasty. It had a profound impact on the social structure, political system, educational system, and humanistic ideologies of China after the Sui and Tang dynasties.", "chunks": ["The imperial civil examination system dominated education in China’s feudal society. It became the primary method through which talented individuals were recognised and appointed as government officials. The practice began in the Sui Dynasty and lasted for about 1,300 years, until the end of the Qing Dynasty. It had a profound impact on the social structure, political system, educational system, and humanistic ideologies of China after the Sui and Tang dynasties."]}, {"id": "u1_s7_p2", "buf": ["During the Ming and Qing dynasties, the imperial civil examination was held once every three years. It featured composition writing, which was designed to select jinshi (进士), the successful candidates in the highest imperial civil examinations. The military examination focused on martial arts, including horsemanship, archery, and weightlifting."], "text": "During the Ming and Qing dynasties, the imperial civil examination was held once every three years. It featured composition writing, which was designed to select jinshi (进士), the successful candidates in the highest imperial civil examinations. The military examination focused on martial arts, including horsemanship, archery, and weightlifting.", "chunks": ["During the Ming and Qing dynasties, the imperial civil examination was held once every three years. It featured composition writing, which was designed to select jinshi (进士), the successful candidates in the highest imperial civil examinations. The military examination focused on martial arts, including horsemanship, archery, and weightlifting."]}, {"id": "u1_s7_p3", "buf": ["In ancient China, the social hierarchy was rigid, and individuals from lower classes had little chance of attaining high office, especially positions in the imperial court. However, with the introduction of the imperial civil examination system, young men from humble backgrounds had the opportunity to attend government examinations, which enabled them to bring honour to their families. Thus, regardless of family background, nearly all males—provided they met certain requirements—were able to pursue official careers and fulfil their potential."], "text": "In ancient China, the social hierarchy was rigid, and individuals from lower classes had little chance of attaining high office, especially positions in the imperial court. However, with the introduction of the imperial civil examination system, young men from humble backgrounds had the opportunity to attend government examinations, which enabled them to bring honour to their families. Thus, regardless of family background, nearly all males—provided they met certain requirements—were able to pursue official careers and fulfil their potential.", "chunks": ["In ancient China, the social hierarchy was rigid, and individuals from lower classes had little chance of attaining high office, especially positions in the imperial court. However, with the introduction of the imperial civil examination system, young men from humble backgrounds had the opportunity to attend government examinations, which enabled them to bring honour to their families. Thus, regardless of family background, nearly all males—provided they met certain requirements—were able to pursue official careers and fulfil their potential."]}, {"id": "u1_s7_p4", "buf": ["The candidate who won first place in the palace examination was called zhuangyuan (状元), and he would be granted a high-ranking position in the court. The one who won second place was called bangyan (榜眼), and the third was called tanhua (探花). They would also be assigned important posts in the government."], "text": "The candidate who won first place in the palace examination was called zhuangyuan (状元), and he would be granted a high-ranking position in the court. The one who won second place was called bangyan (榜眼), and the third was called tanhua (探花). They would also be assigned important posts in the government.", "chunks": ["The candidate who won first place in the palace examination was called zhuangyuan (状元), and he would be granted a high-ranking position in the court. The one who won second place was called bangyan (榜眼), and the third was called tanhua (探花). They would also be assigned important posts in the government."]}, {"id": "u1_s7_p5", "buf": ["During the Ming and Qing dynasties, participants in the imperial civil examinations were required to write essays in strict accordance with an eight-part form, which was known for its rigidity of structure and strict adherence to the ideology of the ruling class. New ideas were often condemned. It is believed that, to a degree, the rigid content and form of the examination constrained people’s thinking and limited cultural progress."], "text": "During the Ming and Qing dynasties, participants in the imperial civil examinations were required to write essays in strict accordance with an eight-part form, which was known for its rigidity of structure and strict adherence to the ideology of the ruling class. New ideas were often condemned. It is believed that, to a degree, the rigid content and form of the examination constrained people’s thinking and limited cultural progress.", "chunks": ["During the Ming and Qing dynasties, participants in the imperial civil examinations were required to write essays in strict accordance with an eight-part form, which was known for its rigidity of structure and strict adherence to the ideology of the ruling class. New ideas were often condemned. It is believed that, to a degree, the rigid content and form of the examination constrained people’s thinking and limited cultural progress."]}, {"id": "u1_s7_p6", "buf": ["After 1840, the imperial civil examination system faced increasing challenges and instability. In an effort to preserve it, the Qing Dynasty introduced a series of reforms, but these ultimately led to the system's decline. In 1905, recognising the demands of the times, the Qing government officially abolished the imperial civil examination system."], "text": "After 1840, the imperial civil examination system faced increasing challenges and instability. In an effort to preserve it, the Qing Dynasty introduced a series of reforms, but these ultimately led to the system's decline. In 1905, recognising the demands of the times, the Qing government officially abolished the imperial civil examination system.", "chunks": ["After 1840, the imperial civil examination system faced increasing challenges and instability. In an effort to preserve it, the Qing Dynasty introduced a series of reforms, but these ultimately led to the system's decline. In 1905, recognising the demands of the times, the Qing government officially abolished the imperial civil examination system."]}]}, {"id": "u1_s8", "title": "新学", "paras": [{"id": "u1_s8_p1", "buf": ["New Learning refers to the political ideas and academic culture introduced into China from the West before the May Fourth Movement, and it is in contrast to the traditional Chinese ideological and cultural concepts known as Old Learning (旧学). After the Revolution of 1911, China introduced an educational system encompassing all levels from primary school to university."], "text": "New Learning refers to the political ideas and academic culture introduced into China from the West before the May Fourth Movement, and it is in contrast to the traditional Chinese ideological and cultural concepts known as Old Learning (旧学). After the Revolution of 1911, China introduced an educational system encompassing all levels from primary school to university.", "chunks": ["New Learning refers to the political ideas and academic culture introduced into China from the West before the May Fourth Movement, and it is in contrast to the traditional Chinese ideological and cultural concepts known as Old Learning (旧学). After the Revolution of 1911, China introduced an educational system encompassing all levels from primary school to university."]}]}]}, {"id": "u2", "title": "现代教育", "sections": [{"id": "u2_s1", "title": "现代教育", "paras": [{"id": "u2_s1_p1", "buf": ["Since 1949, when the People’s Republic of China was founded, education has been a top priority. The government emphasises protecting the educational rights of its population, especially for ethnic minority groups, children, women, and people with disabilities. Through continuous efforts over the past decades, China has made significant progress in education."], "text": "Since 1949, when the People’s Republic of China was founded, education has been a top priority. The government emphasises protecting the educational rights of its population, especially for ethnic minority groups, children, women, and people with disabilities. Through continuous efforts over the past decades, China has made significant progress in education.", "chunks": ["Since 1949, when the People’s Republic of China was founded, education has been a top priority. The government emphasises protecting the educational rights of its population, especially for ethnic minority groups, children, women, and people with disabilities. Through continuous efforts over the past decades, China has made significant progress in education."]}, {"id": "u2_s1_p2", "buf": ["The state implements a school education system that includes preschool, primary, secondary, and higher education. A scientific system of educational grades is established by the state. The establishment, educational forms, duration of study, admission requirements, and training objectives of schools and other educational institutions within this system are determined by the State Council or by the educational administrative departments authorised by the State Council."], "text": "The state implements a school education system that includes preschool, primary, secondary, and higher education. A scientific system of educational grades is established by the state. The establishment, educational forms, duration of study, admission requirements, and training objectives of schools and other educational institutions within this system are determined by the State Council or by the educational administrative departments authorised by the State Council.", "chunks": ["The state implements a school education system that includes preschool, primary, secondary, and higher education. A scientific system of educational grades is established by the state. The establishment, educational forms, duration of study, admission requirements, and training objectives of schools and other educational institutions within this system are determined by the State Council or by the educational administrative departments authorised by the State Council."]}, {"id": "u2_s1_p3", "buf": ["Primary schooling is provided for the entire Chinese population. There has also been rapid development in other levels and types of education, such as secondary education, higher education, vocational education, special education, adult education, and education for ethnic minority groups. Today, the Chinese people have more educational opportunities than ever before across a wider range of institutions and fields."], "text": "Primary schooling is provided for the entire Chinese population. There has also been rapid development in other levels and types of education, such as secondary education, higher education, vocational education, special education, adult education, and education for ethnic minority groups. Today, the Chinese people have more educational opportunities than ever before across a wider range of institutions and fields.", "chunks": ["Primary schooling is provided for the entire Chinese population. There has also been rapid development in other levels and types of education, such as secondary education, higher education, vocational education, special education, adult education, and education for ethnic minority groups. Today, the Chinese people have more educational opportunities than ever before across a wider range of institutions and fields."]}, {"id": "u2_s1_p4", "buf": ["China is fully implementing strategies to reinvigorate the nation through science, education, and human resource development. Its goal is to build an education system that meets the needs and expectations of all its people."], "text": "China is fully implementing strategies to reinvigorate the nation through science, education, and human resource development. Its goal is to build an education system that meets the needs and expectations of all its people.", "chunks": ["China is fully implementing strategies to reinvigorate the nation through science, education, and human resource development. Its goal is to build an education system that meets the needs and expectations of all its people."]}]}, {"id": "u2_s2", "title": "学前教育", "paras": [{"id": "u2_s2_p1", "buf": ["Preschool education refers to the care and instruction provided by kindergartens and similar institutions for children from the age of three until they enter primary school. It is recognised as an essential public service and a vital component of the national education system."], "text": "Preschool education refers to the care and instruction provided by kindergartens and similar institutions for children from the age of three until they enter primary school. It is recognised as an essential public service and a vital component of the national education system.", "chunks": ["Preschool education refers to the care and instruction provided by kindergartens and similar institutions for children from the age of three until they enter primary school. It is recognised as an essential public service and a vital component of the national education system."]}, {"id": "u2_s2_p2", "buf": ["Kindergartens are required to conduct educational activities that are appropriate to the developmental stages and characteristics of preschool children, and the introduction of primary school curricula is strictly prohibited."], "text": "Kindergartens are required to conduct educational activities that are appropriate to the developmental stages and characteristics of preschool children, and the introduction of primary school curricula is strictly prohibited.", "chunks": ["Kindergartens are required to conduct educational activities that are appropriate to the developmental stages and characteristics of preschool children, and the introduction of primary school curricula is strictly prohibited."]}, {"id": "u2_s2_p3", "buf": ["Kindergartens are generally staffed with teachers, principals, caregivers, and healthcare personnel. China has formulated regulations regarding the qualifications and performance assessment of kindergarten teachers, who are required to undergo formal training in preschool education."], "text": "Kindergartens are generally staffed with teachers, principals, caregivers, and healthcare personnel. China has formulated regulations regarding the qualifications and performance assessment of kindergarten teachers, who are required to undergo formal training in preschool education.", "chunks": ["Kindergartens are generally staffed with teachers, principals, caregivers, and healthcare personnel. China has formulated regulations regarding the qualifications and performance assessment of kindergarten teachers, who are required to undergo formal training in preschool education."]}]}, {"id": "u2_s3", "title": "九年义务教育", "paras": [{"id": "u2_s3_p1", "buf": ["The Compulsory Education Law of the People’s Republic of China came into effect on 1st July 1986, requiring all children to complete nine years of formal education. The nine-year compulsory education consists of both primary and junior middle school levels."], "text": "The Compulsory Education Law of the People’s Republic of China came into effect on 1st July 1986, requiring all children to complete nine years of formal education. The nine-year compulsory education consists of both primary and junior middle school levels.", "chunks": ["The Compulsory Education Law of the People’s Republic of China came into effect on 1st July 1986, requiring all children to complete nine years of formal education. The nine-year compulsory education consists of both primary and junior middle school levels."]}, {"id": "u2_s3_p2", "buf": ["In China, generally, all children who reach the age of six are required to enter primary school. In areas where conditions are not adequate, children may start school at seven. Primary school graduates can proceed to junior middle school without entrance examinations. When students finish their schooling in junior middle school, they may choose to attend vocational school or continue with a general education in senior middle school. In their final year, junior middle school students take the academic proficiency examination. The results of this exam serve two important functions: determining whether students meet the requirements for graduation, and serving as the basis for admission to senior middle school."], "text": "In China, generally, all children who reach the age of six are required to enter primary school. In areas where conditions are not adequate, children may start school at seven. Primary school graduates can proceed to junior middle school without entrance examinations. When students finish their schooling in junior middle school, they may choose to attend vocational school or continue with a general education in senior middle school. In their final year, junior middle school students take the academic proficiency examination. The results of this exam serve two important functions: determining whether students meet the requirements for graduation, and serving as the basis for admission to senior middle school.", "chunks": ["In China, generally, all children who reach the age of six are required to enter primary school. In areas where conditions are not adequate, children may start school at seven. Primary school graduates can proceed to junior middle school without entrance examinations. When students finish their schooling in junior middle school, they may choose to attend vocational school or continue with a general education in senior middle school. In their final year, junior middle school students take the academic proficiency examination. The results of this exam serve two important functions: determining whether students meet the requirements for graduation, and serving as the basis for admission to senior middle school."]}, {"id": "u2_s3_p3", "buf": ["The government plays a leading role in school education, while privately run schools serve as a supplementary part of the education system. Full-time primary and secondary schools run by the state are the main providers of education at these levels. At the same time, private organisations are encouraged to contribute funds to the establishment and operation of schools, including primary and secondary schools."], "text": "The government plays a leading role in school education, while privately run schools serve as a supplementary part of the education system. Full-time primary and secondary schools run by the state are the main providers of education at these levels. At the same time, private organisations are encouraged to contribute funds to the establishment and operation of schools, including primary and secondary schools.", "chunks": ["The government plays a leading role in school education, while privately run schools serve as a supplementary part of the education system. Full-time primary and secondary schools run by the state are the main providers of education at these levels. At the same time, private organisations are encouraged to contribute funds to the establishment and operation of schools, including primary and secondary schools."]}, {"id": "u2_s3_p4", "buf": ["The school curriculum is designed to help students develop their qualities of sound moral grounding, intellectual ability, physical vigour, aesthetic sensibility, and work skills. It is tailored to the cognitive and developmental needs of children at different ages and puts emphasis on the integration of book knowledge, social life, and students’ learning experiences."], "text": "The school curriculum is designed to help students develop their qualities of sound moral grounding, intellectual ability, physical vigour, aesthetic sensibility, and work skills. It is tailored to the cognitive and developmental needs of children at different ages and puts emphasis on the integration of book knowledge, social life, and students’ learning experiences.", "chunks": ["The school curriculum is designed to help students develop their qualities of sound moral grounding, intellectual ability, physical vigour, aesthetic sensibility, and work skills. It is tailored to the cognitive and developmental needs of children at different ages and puts emphasis on the integration of book knowledge, social life, and students’ learning experiences."]}, {"id": "u2_s3_p5", "buf": ["The state and society provide various forms of financial assistance to children, adolescents, and youth from economically disadvantaged families who are eligible to attend school. In 1989, China launched two initiatives: Project Hope (希望工程) and the Spring Bud Project (春蕾计划). These two projects have helped children, especially girls, in impoverished areas attend school."], "text": "The state and society provide various forms of financial assistance to children, adolescents, and youth from economically disadvantaged families who are eligible to attend school. In 1989, China launched two initiatives: Project Hope (希望工程) and the Spring Bud Project (春蕾计划). These two projects have helped children, especially girls, in impoverished areas attend school.", "chunks": ["The state and society provide various forms of financial assistance to children, adolescents, and youth from economically disadvantaged families who are eligible to attend school. In 1989, China launched two initiatives: Project Hope (希望工程) and the Spring Bud Project (春蕾计划). These two projects have helped children, especially girls, in impoverished areas attend school."]}]}, {"id": "u2_s4", "title": "高中与中等职业学校", "paras": []}, {"id": "u2_s5", "title": "高中", "paras": [{"id": "u2_s5_p1", "buf": ["The three-year senior middle school education prepares students for further study at college or university, as well as for entering the workforce or pursuing vocational training. During these three years, students must take and pass graduation examinations in a range of subjects at different stages to receive the Senior Middle School Graduation Certificate (高中毕业证书)."], "text": "The three-year senior middle school education prepares students for further study at college or university, as well as for entering the workforce or pursuing vocational training. During these three years, students must take and pass graduation examinations in a range of subjects at different stages to receive the Senior Middle School Graduation Certificate (高中毕业证书).", "chunks": ["The three-year senior middle school education prepares students for further study at college or university, as well as for entering the workforce or pursuing vocational training. During these three years, students must take and pass graduation examinations in a range of subjects at different stages to receive the Senior Middle School Graduation Certificate (高中毕业证书)."]}]}, {"id": "u2_s6", "title": "中等职业学校", "paras": [{"id": "u2_s6_p1", "buf": ["Secondary vocational education is an alternative to senior middle school. Its objective is to prepare students for careers in production, technical services, management, and other related fields. After three or four years of study, graduates can either enter the workforce in their chosen fields or take the National College Entrance Examination (NCEE: 高考) to pursue higher education."], "text": "Secondary vocational education is an alternative to senior middle school. Its objective is to prepare students for careers in production, technical services, management, and other related fields. After three or four years of study, graduates can either enter the workforce in their chosen fields or take the National College Entrance Examination (NCEE: 高考) to pursue higher education.", "chunks": ["Secondary vocational education is an alternative to senior middle school. Its objective is to prepare students for careers in production, technical services, management, and other related fields. After three or four years of study, graduates can either enter the workforce in their chosen fields or take the National College Entrance Examination (NCEE: 高考) to pursue higher education."]}]}, {"id": "u2_s7", "title": "高考", "paras": [{"id": "u2_s7_p1", "buf": ["Students who wish to pursue higher education must take the NCEE at the end of their third year of senior middle school. Currently, the policies regarding NCEE vary across provinces in China. Most provinces have implemented new policies that no longer separate students into science and liberal arts streams, while some provinces continue to follow the traditional system that maintains this distinction."], "text": "Students who wish to pursue higher education must take the NCEE at the end of their third year of senior middle school. Currently, the policies regarding NCEE vary across provinces in China. Most provinces have implemented new policies that no longer separate students into science and liberal arts streams, while some provinces continue to follow the traditional system that maintains this distinction.", "chunks": ["Students who wish to pursue higher education must take the NCEE at the end of their third year of senior middle school. Currently, the policies regarding NCEE vary across provinces in China. Most provinces have implemented new policies that no longer separate students into science and liberal arts streams, while some provinces continue to follow the traditional system that maintains this distinction."]}, {"id": "u2_s7_p2", "buf": ["The NCEE is an academic examination held annually in China, aimed at selecting senior middle school graduates for college admission. It is held at the end of the spring semester, and prospective graduates across the country take the examination simultaneously. By standardising university admissions, the NCEE ensures a merit-based process that allows students from all backgrounds to compete fairly. The exam’s rigorous and transparent nature fosters accountability and equal opportunity, helping to level the playing field for millions."], "text": "The NCEE is an academic examination held annually in China, aimed at selecting senior middle school graduates for college admission. It is held at the end of the spring semester, and prospective graduates across the country take the examination simultaneously. By standardising university admissions, the NCEE ensures a merit-based process that allows students from all backgrounds to compete fairly. The exam’s rigorous and transparent nature fosters accountability and equal opportunity, helping to level the playing field for millions.", "chunks": ["The NCEE is an academic examination held annually in China, aimed at selecting senior middle school graduates for college admission. It is held at the end of the spring semester, and prospective graduates across the country take the examination simultaneously. By standardising university admissions, the NCEE ensures a merit-based process that allows students from all backgrounds to compete fairly. The exam’s rigorous and transparent nature fosters accountability and equal opportunity, helping to level the playing field for millions."]}, {"id": "u2_s7_p3", "buf": ["Additionally, ongoing reforms have made the exam more flexible and better at recognising diverse talents. Targeted support programmes help students from underprivileged regions gain access to higher education, further promoting educational equity across the country."], "text": "Additionally, ongoing reforms have made the exam more flexible and better at recognising diverse talents. Targeted support programmes help students from underprivileged regions gain access to higher education, further promoting educational equity across the country.", "chunks": ["Additionally, ongoing reforms have made the exam more flexible and better at recognising diverse talents. Targeted support programmes help students from underprivileged regions gain access to higher education, further promoting educational equity across the country."]}]}, {"id": "u2_s8", "title": "高等教育", "paras": [{"id": "u2_s8_p1", "buf": ["The origins of higher education in China are a subject of scholarly debate. Some historians trace its beginnings to the Western Zhou Dynasty, while others point to the Taixue (太学) of the Han Dynasty. The Han Dynasty government established Taixue as the highest educational institution to cultivate senior scholars to help administer national affairs. Beginning in the Sui Dynasty, the institution for higher education became known as Guozijian (国子监). It served both as the highest educational institution in the country and as the administrative body responsible for overseeing education."], "text": "The origins of higher education in China are a subject of scholarly debate. Some historians trace its beginnings to the Western Zhou Dynasty, while others point to the Taixue (太学) of the Han Dynasty. The Han Dynasty government established Taixue as the highest educational institution to cultivate senior scholars to help administer national affairs. Beginning in the Sui Dynasty, the institution for higher education became known as Guozijian (国子监). It served both as the highest educational institution in the country and as the administrative body responsible for overseeing education.", "chunks": ["The origins of higher education in China are a subject of scholarly debate. Some historians trace its beginnings to the Western Zhou Dynasty, while others point to the Taixue (太学) of the Han Dynasty. The Han Dynasty government established Taixue as the highest educational institution to cultivate senior scholars to help administer national affairs. Beginning in the Sui Dynasty, the institution for higher education became known as Guozijian (国子监). It served both as the highest educational institution in the country and as the administrative body responsible for overseeing education."]}, {"id": "u2_s8_p2", "buf": ["Today, China has established the world’s largest higher education system, offering many opportunities to study in a variety of institutions across diverse disciplines. More than 3,000 institutions of higher education in China offer a wide range of programmes. Students who have earned a bachelor’s degree may apply for master’s degree programmes, and after completing a master’s degree, they have the option to pursue doctoral studies."], "text": "Today, China has established the world’s largest higher education system, offering many opportunities to study in a variety of institutions across diverse disciplines. More than 3,000 institutions of higher education in China offer a wide range of programmes. Students who have earned a bachelor’s degree may apply for master’s degree programmes, and after completing a master’s degree, they have the option to pursue doctoral studies.", "chunks": ["Today, China has established the world’s largest higher education system, offering many opportunities to study in a variety of institutions across diverse disciplines. More than 3,000 institutions of higher education in China offer a wide range of programmes. Students who have earned a bachelor’s degree may apply for master’s degree programmes, and after completing a master’s degree, they have the option to pursue doctoral studies."]}, {"id": "u2_s8_p3", "buf": ["Undergraduate education enables students to systematically master the fundamental theories and knowledge required for their disciplines and majors, acquire essential skills and methods related to their specialities, and develop the foundational ability to undertake practical work and research in their fields. College and university students also have a wide range of extracurricular activities to choose from. Students can join various associations, such as student unions and student-run organisations based on shared athletic, academic, or recreational interests. These associations generally have regular activities, promoting interaction, understanding, and friendship among students."], "text": "Undergraduate education enables students to systematically master the fundamental theories and knowledge required for their disciplines and majors, acquire essential skills and methods related to their specialities, and develop the foundational ability to undertake practical work and research in their fields. College and university students also have a wide range of extracurricular activities to choose from. Students can join various associations, such as student unions and student-run organisations based on shared athletic, academic, or recreational interests. These associations generally have regular activities, promoting interaction, understanding, and friendship among students.", "chunks": ["Undergraduate education enables students to systematically master the fundamental theories and knowledge required for their disciplines and majors, acquire essential skills and methods related to their specialities, and develop the foundational ability to undertake practical work and research in their fields. College and university students also have a wide range of extracurricular activities to choose from. Students can join various associations, such as student unions and student-run organisations based on shared athletic, academic, or recreational interests. These associations generally have regular activities, promoting interaction, understanding, and friendship among students."]}, {"id": "u2_s8_p4", "buf": ["Today, China is taking more action to expand high-level opening up. More Chinese-foreign cooperation in running schools is strengthening higher education and vocational education, and more high-quality foreign educational resources are being introduced."], "text": "Today, China is taking more action to expand high-level opening up. More Chinese-foreign cooperation in running schools is strengthening higher education and vocational education, and more high-quality foreign educational resources are being introduced.", "chunks": ["Today, China is taking more action to expand high-level opening up. More Chinese-foreign cooperation in running schools is strengthening higher education and vocational education, and more high-quality foreign educational resources are being introduced."]}, {"id": "u2_s8_p5", "buf": ["Launched in 1995, Project 211 is a national initiative in China aimed at strengthening approximately 100 key universities and a number of academic disciplines to enhance their academic standards and global competitiveness. Its goal is to improve the quality of education, research capabilities, and institutional management, bringing these universities in line with leading universities worldwide. Project 985, launched in 1998, aims to develop a select group of world-class universities and internationally renowned high-level research universities. The project represents a strategic effort to elevate China’s higher education to align with leading global standards. Building on these projects, China continues to advance the “Double First-Class (双一流)” Initiative, which focuses on cultivating world-class universities and academic disciplines that reflect Chinese characteristics."], "text": "Launched in 1995, Project 211 is a national initiative in China aimed at strengthening approximately 100 key universities and a number of academic disciplines to enhance their academic standards and global competitiveness. Its goal is to improve the quality of education, research capabilities, and institutional management, bringing these universities in line with leading universities worldwide. Project 985, launched in 1998, aims to develop a select group of world-class universities and internationally renowned high-level research universities. The project represents a strategic effort to elevate China’s higher education to align with leading global standards. Building on these projects, China continues to advance the “Double First-Class (双一流)” Initiative, which focuses on cultivating world-class universities and academic disciplines that reflect Chinese characteristics.", "chunks": ["Launched in 1995, Project 211 is a national initiative in China aimed at strengthening approximately 100 key universities and a number of academic disciplines to enhance their academic standards and global competitiveness. Its goal is to improve the quality of education, research capabilities, and institutional management, bringing these universities in line with leading universities worldwide. Project 985, launched in 1998, aims to develop a select group of world-class universities and internationally renowned high-level research universities. The project represents a strategic effort to elevate China’s higher education to align with leading global standards. Building on these projects, China continues to advance the “Double First-Class (双一流)” Initiative, which focuses on cultivating world-class universities and academic disciplines that reflect Chinese characteristics."]}]}, {"id": "u2_s9", "title": "职业教育", "paras": [{"id": "u2_s9_p1", "buf": ["China’s vocational education consists of vocational schooling and vocational training. Vocational school education is divided into secondary and higher vocational education, while vocational training includes pre-employment training, on-the-job training, re-employment training, and other career-focused programmes. This system aims to equip individuals with practical skills and knowledge for various industries and professions. As of 2023, China has established the world’s largest vocational education system, with over 11,000 vocational schools and 35 million enrolled students. More than 10 million students graduate each year. Through international collaboration, China's vocational education has evolved to train skilled professionals needed for global economic and social development, serving as a bridge for international trade and cultural exchange."], "text": "China’s vocational education consists of vocational schooling and vocational training. Vocational school education is divided into secondary and higher vocational education, while vocational training includes pre-employment training, on-the-job training, re-employment training, and other career-focused programmes. This system aims to equip individuals with practical skills and knowledge for various industries and professions. As of 2023, China has established the world’s largest vocational education system, with over 11,000 vocational schools and 35 million enrolled students. More than 10 million students graduate each year. Through international collaboration, China's vocational education has evolved to train skilled professionals needed for global economic and social development, serving as a bridge for international trade and cultural exchange.", "chunks": ["China’s vocational education consists of vocational schooling and vocational training. Vocational school education is divided into secondary and higher vocational education, while vocational training includes pre-employment training, on-the-job training, re-employment training, and other career-focused programmes. This system aims to equip individuals with practical skills and knowledge for various industries and professions. As of 2023, China has established the world’s largest vocational education system, with over 11,000 vocational schools and 35 million enrolled students. More than 10 million students graduate each year. Through international collaboration, China's vocational education has evolved to train skilled professionals needed for global economic and social development, serving as a bridge for international trade and cultural exchange."]}]}, {"id": "u2_s10", "title": "成人教育", "paras": [{"id": "u2_s10_p1", "buf": ["China's adult education is a distinct form of education designed for adults, aiming to enhance their skills, knowledge, and professional qualifications. It is part of the national education system and includes various forms such as evening classes, correspondence courses, self-study programmes, and open university education, all of which are officially recognised and accredited. Primarily catering to working professionals, adult education provides opportunities for career advancement, specialised training, and further education beyond traditional schooling."], "text": "China's adult education is a distinct form of education designed for adults, aiming to enhance their skills, knowledge, and professional qualifications. It is part of the national education system and includes various forms such as evening classes, correspondence courses, self-study programmes, and open university education, all of which are officially recognised and accredited. Primarily catering to working professionals, adult education provides opportunities for career advancement, specialised training, and further education beyond traditional schooling.", "chunks": ["China's adult education is a distinct form of education designed for adults, aiming to enhance their skills, knowledge, and professional qualifications. It is part of the national education system and includes various forms such as evening classes, correspondence courses, self-study programmes, and open university education, all of which are officially recognised and accredited. Primarily catering to working professionals, adult education provides opportunities for career advancement, specialised training, and further education beyond traditional schooling."]}]}, {"id": "u2_s11", "title": "特殊教育", "paras": [{"id": "u2_s11_p1", "buf": ["Special education refers to personalised educational services designed for individuals with physical, mental, or learning disabilities. It provides equitable developmental opportunities through adapted curricula, specialised instruction, and assistive technologies. The target group includes individuals with visual or hearing impairments, speech and language disorders, and intellectual or physical disabilities, as well as mental health challenges and learning disabilities."], "text": "Special education refers to personalised educational services designed for individuals with physical, mental, or learning disabilities. It provides equitable developmental opportunities through adapted curricula, specialised instruction, and assistive technologies. The target group includes individuals with visual or hearing impairments, speech and language disorders, and intellectual or physical disabilities, as well as mental health challenges and learning disabilities.", "chunks": ["Special education refers to personalised educational services designed for individuals with physical, mental, or learning disabilities. It provides equitable developmental opportunities through adapted curricula, specialised instruction, and assistive technologies. The target group includes individuals with visual or hearing impairments, speech and language disorders, and intellectual or physical disabilities, as well as mental health challenges and learning disabilities."]}, {"id": "u2_s11_p2", "buf": ["The Chinese government has always attached great importance to special education. The state has issued a set of laws and regulations that explicitly safeguard the right to education for people with disabilities, and has formulated a series of general and specific policies for reforming and developing special education, while allocating (划拨) dedicated funds for this purpose. As a result, special education has developed rapidly in China."], "text": "The Chinese government has always attached great importance to special education. The state has issued a set of laws and regulations that explicitly safeguard the right to education for people with disabilities, and has formulated a series of general and specific policies for reforming and developing special education, while allocating (划拨) dedicated funds for this purpose. As a result, special education has developed rapidly in China.", "chunks": ["The Chinese government has always attached great importance to special education. The state has issued a set of laws and regulations that explicitly safeguard the right to education for people with disabilities, and has formulated a series of general and specific policies for reforming and developing special education, while allocating (划拨) dedicated funds for this purpose. As a result, special education has developed rapidly in China."]}]}, {"id": "u2_s12", "title": "少数民族教育", "paras": [{"id": "u2_s12_p1", "buf": ["China is a unified multi-ethnic country. Education for ethnic minority groups is an important component of China’s educational strategy. After 1949, the Chinese government paid considerable attention to its development. Administrative organs have been set up in educational departments at both the central and local levels to implement the country’s policies regarding education for ethnic minority groups."], "text": "China is a unified multi-ethnic country. Education for ethnic minority groups is an important component of China’s educational strategy. After 1949, the Chinese government paid considerable attention to its development. Administrative organs have been set up in educational departments at both the central and local levels to implement the country’s policies regarding education for ethnic minority groups.", "chunks": ["China is a unified multi-ethnic country. Education for ethnic minority groups is an important component of China’s educational strategy. After 1949, the Chinese government paid considerable attention to its development. Administrative organs have been set up in educational departments at both the central and local levels to implement the country’s policies regarding education for ethnic minority groups."]}, {"id": "u2_s12_p2", "buf": ["The government has been addressing the unique challenges related to education for these groups, and funds have been allocated to meet the financial needs."], "text": "The government has been addressing the unique challenges related to education for these groups, and funds have been allocated to meet the financial needs.", "chunks": ["The government has been addressing the unique challenges related to education for these groups, and funds have been allocated to meet the financial needs."]}, {"id": "u2_s12_p3", "buf": ["Schools of all categories and at all levels have trained a large number of ethnic minority individuals. These people have made great contributions to the economic and social development of ethnic minority regions and to China as a whole."], "text": "Schools of all categories and at all levels have trained a large number of ethnic minority individuals. These people have made great contributions to the economic and social development of ethnic minority regions and to China as a whole.", "chunks": ["Schools of all categories and at all levels have trained a large number of ethnic minority individuals. These people have made great contributions to the economic and social development of ethnic minority regions and to China as a whole."]}]}, {"id": "u2_s13", "title": "国际交流与合作", "paras": [{"id": "u2_s13_p1", "buf": ["In 1978, one of China’s most significant basic policies, reform and opening up, was adopted. At that point, international exchange and cooperation in education entered a new era. Students were encouraged to study abroad, and the number of international students studying in China greatly increased. International academic exchange and cooperation have promoted educational reform and development in China, and have enhanced mutual understanding and friendship between China and other countries."], "text": "In 1978, one of China’s most significant basic policies, reform and opening up, was adopted. At that point, international exchange and cooperation in education entered a new era. Students were encouraged to study abroad, and the number of international students studying in China greatly increased. International academic exchange and cooperation have promoted educational reform and development in China, and have enhanced mutual understanding and friendship between China and other countries.", "chunks": ["In 1978, one of China’s most significant basic policies, reform and opening up, was adopted. At that point, international exchange and cooperation in education entered a new era. Students were encouraged to study abroad, and the number of international students studying in China greatly increased. International academic exchange and cooperation have promoted educational reform and development in China, and have enhanced mutual understanding and friendship between China and other countries."]}]}, {"id": "u2_s14", "title": "出国留学", "paras": [{"id": "u2_s14_p1", "buf": ["It has been more than 100 years since China began sending students and scholars abroad to study. From the implementation of the reform and opening-up policy to the end of 2024, around 10 million Chinese students have studied overseas, with approximately 8 million returning to China after completing their studies."], "text": "It has been more than 100 years since China began sending students and scholars abroad to study. From the implementation of the reform and opening-up policy to the end of 2024, around 10 million Chinese students have studied overseas, with approximately 8 million returning to China after completing their studies.", "chunks": ["It has been more than 100 years since China began sending students and scholars abroad to study. From the implementation of the reform and opening-up policy to the end of 2024, around 10 million Chinese students have studied overseas, with approximately 8 million returning to China after completing their studies."]}, {"id": "u2_s14_p2", "buf": ["In recent years, an increasing number of students studying abroad have chosen to return and develop their careers domestically. With the solid implementation of more open talent policies, China has become increasingly attractive to overseas-educated Chinese talent. Various types of returned talent are rapidly gathering to contribute to the building of a modern socialist country."], "text": "In recent years, an increasing number of students studying abroad have chosen to return and develop their careers domestically. With the solid implementation of more open talent policies, China has become increasingly attractive to overseas-educated Chinese talent. Various types of returned talent are rapidly gathering to contribute to the building of a modern socialist country.", "chunks": ["In recent years, an increasing number of students studying abroad have chosen to return and develop their careers domestically. With the solid implementation of more open talent policies, China has become increasingly attractive to overseas-educated Chinese talent. Various types of returned talent are rapidly gathering to contribute to the building of a modern socialist country."]}]}, {"id": "u2_s15", "title": "来华留学生", "paras": [{"id": "u2_s15_p1", "buf": ["China continues to strengthen its capacity to train and attract global talent, promote youth exchanges with other countries, and implement international summer school programmes. These efforts have successfully enabled the development of expertise in fields such as science, technology, education, diplomacy, and management, benefiting many countries, particularly developing nations. They have made significant contributions to strengthening political, diplomatic, and economic relations between China and these countries, while also promoting cultural, educational, and professional exchanges."], "text": "China continues to strengthen its capacity to train and attract global talent, promote youth exchanges with other countries, and implement international summer school programmes. These efforts have successfully enabled the development of expertise in fields such as science, technology, education, diplomacy, and management, benefiting many countries, particularly developing nations. They have made significant contributions to strengthening political, diplomatic, and economic relations between China and these countries, while also promoting cultural, educational, and professional exchanges.", "chunks": ["China continues to strengthen its capacity to train and attract global talent, promote youth exchanges with other countries, and implement international summer school programmes. These efforts have successfully enabled the development of expertise in fields such as science, technology, education, diplomacy, and management, benefiting many countries, particularly developing nations. They have made significant contributions to strengthening political, diplomatic, and economic relations between China and these countries, while also promoting cultural, educational, and professional exchanges."]}, {"id": "u2_s15_p2", "buf": ["In 1950, China received the first group of 33 students from Eastern European countries. By 2018, nearly 500,000 students from almost 200 countries were studying at more than 1,000 higher education institutions in China. China’s international education is gaining global influence, attracting a growing number of students from around the world. Over time, international students have shifted from primarily studying the Chinese language to pursuing diverse disciplines such as medicine, engineering, economics, and management. The demographics of international students have also diversified, with more students coming from developed countries in Europe and North America. There has also been a significant increase in students enrolling in degree programmes rather than short-term language courses."], "text": "In 1950, China received the first group of 33 students from Eastern European countries. By 2018, nearly 500,000 students from almost 200 countries were studying at more than 1,000 higher education institutions in China. China’s international education is gaining global influence, attracting a growing number of students from around the world. Over time, international students have shifted from primarily studying the Chinese language to pursuing diverse disciplines such as medicine, engineering, economics, and management. The demographics of international students have also diversified, with more students coming from developed countries in Europe and North America. There has also been a significant increase in students enrolling in degree programmes rather than short-term language courses.", "chunks": ["In 1950, China received the first group of 33 students from Eastern European countries. By 2018, nearly 500,000 students from almost 200 countries were studying at more than 1,000 higher education institutions in China. China’s international education is gaining global influence, attracting a growing number of students from around the world. Over time, international students have shifted from primarily studying the Chinese language to pursuing diverse disciplines such as medicine, engineering, economics, and management. The demographics of international students have also diversified, with more students coming from developed countries in Europe and North America. There has also been a significant increase in students enrolling in degree programmes rather than short-term language courses."]}]}, {"id": "u2_s16", "title": "学术交流与合作", "paras": [{"id": "u2_s16_p1", "buf": ["Since China implemented the reform and opening-up policy, international academic exchanges have developed rapidly. Not only have a large number of Chinese scholars travelled abroad to attend international academic conferences, but the number of such conferences held in China has also increased. It has become a growing trend for Chinese institutions of higher education to collaborate on scientific research with their international counterparts."], "text": "Since China implemented the reform and opening-up policy, international academic exchanges have developed rapidly. Not only have a large number of Chinese scholars travelled abroad to attend international academic conferences, but the number of such conferences held in China has also increased. It has become a growing trend for Chinese institutions of higher education to collaborate on scientific research with their international counterparts.", "chunks": ["Since China implemented the reform and opening-up policy, international academic exchanges have developed rapidly. Not only have a large number of Chinese scholars travelled abroad to attend international academic conferences, but the number of such conferences held in China has also increased. It has become a growing trend for Chinese institutions of higher education to collaborate on scientific research with their international counterparts."]}, {"id": "u2_s16_p2", "buf": ["High-level cultural and educational exchanges have gathered momentum in recent years. China’s partnership with UNESCO began a new chapter through China’s further participation in international programmes in education, science, and culture. The Chinese government has actively participated in and supported major UNESCO initiatives, building a global platform for high-level educational cooperation and contributing to global educational governance."], "text": "High-level cultural and educational exchanges have gathered momentum in recent years. China’s partnership with UNESCO began a new chapter through China’s further participation in international programmes in education, science, and culture. The Chinese government has actively participated in and supported major UNESCO initiatives, building a global platform for high-level educational cooperation and contributing to global educational governance.", "chunks": ["High-level cultural and educational exchanges have gathered momentum in recent years. China’s partnership with UNESCO began a new chapter through China’s further participation in international programmes in education, science, and culture. The Chinese government has actively participated in and supported major UNESCO initiatives, building a global platform for high-level educational cooperation and contributing to global educational governance."]}]}, {"id": "u2_s17", "title": "汉语国际推广", "paras": [{"id": "u2_s17_p1", "buf": ["By the end of 2020, more than 180 countries and regions around the world had launched Chinese language education programmes, with more than 70 countries incorporating Chinese into their national education systems. The number of international learners of Chinese has since exceeded 20 million. Online Chinese education is also thriving. For example, the “Chinese-Plus” cloud platform provides high-quality resources to users in 202 countries and regions, offering over 30,000 online courses to more than 10 million registered users. The international status of the Chinese language continues to rise, and in 2021, Chinese officially became one of the official languages of the United Nations World Tourism Organization."], "text": "By the end of 2020, more than 180 countries and regions around the world had launched Chinese language education programmes, with more than 70 countries incorporating Chinese into their national education systems. The number of international learners of Chinese has since exceeded 20 million. Online Chinese education is also thriving. For example, the “Chinese-Plus” cloud platform provides high-quality resources to users in 202 countries and regions, offering over 30,000 online courses to more than 10 million registered users. The international status of the Chinese language continues to rise, and in 2021, Chinese officially became one of the official languages of the United Nations World Tourism Organization.", "chunks": ["By the end of 2020, more than 180 countries and regions around the world had launched Chinese language education programmes, with more than 70 countries incorporating Chinese into their national education systems. The number of international learners of Chinese has since exceeded 20 million. Online Chinese education is also thriving. For example, the “Chinese-Plus” cloud platform provides high-quality resources to users in 202 countries and regions, offering over 30,000 online courses to more than 10 million registered users. The international status of the Chinese language continues to rise, and in 2021, Chinese officially became one of the official languages of the United Nations World Tourism Organization."]}]}, {"id": "u2_s18", "title": "孔子学院", "paras": [{"id": "u2_s18_p1", "buf": ["Confucius Institutes are non-profit educational institutions jointly established by Chinese and overseas partner institutions, based on the principles of mutual respect, friendly consultation, equality, and mutual benefit."], "text": "Confucius Institutes are non-profit educational institutions jointly established by Chinese and overseas partner institutions, based on the principles of mutual respect, friendly consultation, equality, and mutual benefit.", "chunks": ["Confucius Institutes are non-profit educational institutions jointly established by Chinese and overseas partner institutions, based on the principles of mutual respect, friendly consultation, equality, and mutual benefit."]}, {"id": "u2_s18_p2", "buf": ["From initial exploration to large-scale development, Confucius Institutes have grown to become some of the largest and most prominent language and cultural education organisations in the world. By the end of 2024, 500 Confucius Institutes and 763 Confucius Classrooms had been established through collaborations between Chinese and local partners in 161 countries and regions."], "text": "From initial exploration to large-scale development, Confucius Institutes have grown to become some of the largest and most prominent language and cultural education organisations in the world. By the end of 2024, 500 Confucius Institutes and 763 Confucius Classrooms had been established through collaborations between Chinese and local partners in 161 countries and regions.", "chunks": ["From initial exploration to large-scale development, Confucius Institutes have grown to become some of the largest and most prominent language and cultural education organisations in the world. By the end of 2024, 500 Confucius Institutes and 763 Confucius Classrooms had been established through collaborations between Chinese and local partners in 161 countries and regions."]}]}]}], "vocabA": [{"term": "four great classical academies", "zh": "四大书院", "q": "• Do you know what the four great classical academies (四大书院) in ancient China were?", "tr": "- 你知道中国古代的四大书院是哪些吗？", "pos": "术语", "src": "原文"}, {"term": "the Four Books and the Five Classics", "zh": "四书五经", "q": "• Can you name the Four Books and the Five Classics (“四书五经”)?", "tr": "- 你能说出“四书五经”吗？", "pos": "术语", "src": "原文"}, {"term": "traditional education", "zh": "传统教育", "q": "", "tr": "", "pos": "术语", "src": "原文"}, {"term": "private schools", "zh": "私学", "q": "During the Spring and Autumn Period, private schools began to emerge, and many scholars of different schools of thought spread their teachings through private instruction. Among them, Confucius’s priv", "tr": "春秋时期，私学开始兴起，诸子百家的许多学者都通过私人讲学来传播自己的学说。其中，孔子的私人讲学影响最大、流传最广。孔子毕生致力于教育，教授了许多学生。相传他有弟子三千，其中七十二人尤为杰出，后来都成为儒家学说的传播者。", "pos": "术语", "src": "原文"}, {"term": "official schools", "zh": "官学", "q": "Since ancient times, education and scholarship have been highly valued in China. The country accumulated extensive experience in establishing both private and official schools, creating educational ne", "tr": "自古以来，中国就高度重视教育与学问。中国在兴办官学与私学、按行政区划构建教育网络、推动多渠道多层次办学等方面积累了丰富的经验。古代中国实行科举制度、书院制度等。这些做法不仅使中国跻身于教育最发达的社会之列，而且在内容和形式上都具有许多独特之处。", "pos": "术语", "src": "原文"}, {"term": "classical academies", "zh": "书院", "q": "• Do you know what the four great classical academies (四大书院) in ancient China were?", "tr": "- 你知道中国古代的四大书院是哪些吗？", "pos": "术语", "src": "原文"}, {"term": "imperial civil examination system", "zh": "科举制度", "q": "• Do you know when the imperial civil examination system began and when it was abolished?", "tr": "- 你知道科举制度始于何时、又于何时废止吗？", "pos": "制度", "src": "原文"}, {"term": "New Learning", "zh": "新学", "q": "New Learning refers to the political ideas and academic culture introduced into China from the West before the May Fourth Movement, and it is in contrast to the traditional Chinese ideological and cul", "tr": "新学指五四运动以前从西方传入中国的政治思想和学术文化，与被称为“旧学”的中国传统思想文化观念相对。辛亥革命后，中国引入了涵盖从小学到大学各级的学校教育制度。", "pos": "术语", "src": "原文"}, {"term": "Old Learning", "zh": "旧学", "q": "New Learning refers to the political ideas and academic culture introduced into China from the West before the May Fourth Movement, and it is in contrast to the traditional Chinese ideological and cul", "tr": "新学指五四运动以前从西方传入中国的政治思想和学术文化，与被称为“旧学”的中国传统思想文化观念相对。辛亥革命后，中国引入了涵盖从小学到大学各级的学校教育制度。", "pos": "术语", "src": "原文"}, {"term": "present education", "zh": "现代教育", "q": "", "tr": "", "pos": "术语", "src": "原文"}, {"term": "preschool education", "zh": "学前教育", "q": "Preschool education refers to the care and instruction provided by kindergartens and similar institutions for children from the age of three until they enter primary school. It is recognised as an ess", "tr": "学前教育指幼儿园及类似机构为3岁至入小学前的儿童提供的保育和教育。它被视为一项基本的公共服务，也是国民教育体系的重要组成部分。", "pos": "术语", "src": "原文"}, {"term": "Nine-Year Compulsory Education", "zh": "九年义务教育", "q": "The Compulsory Education Law of the People’s Republic of China came into effect on 1st July 1986, requiring all children to complete nine years of formal education. The nine-year compulsory education ", "tr": "《中华人民共和国义务教育法》于1986年7月1日起施行，要求所有儿童完成九年正规教育。九年义务教育由小学和初中两个阶段组成。", "pos": "术语", "src": "原文"}, {"term": "senior middle school", "zh": "高中", "q": "In China, generally, all children who reach the age of six are required to enter primary school. In areas where conditions are not adequate, children may start school at seven. Primary school graduate", "tr": "在中国，凡年满6周岁的儿童一般都应入小学就读。条件不具备的地区，儿童可推迟到7岁入学。小学毕业生可免试升入初中。初中毕业后，学生可以选择就读职业学校，或升入高中继续接受普通教育。初中学生在最后一年参加学业水平考试。该考试成绩有两个重要作用：判定学生是否达到毕业要求，以及作为升入高中的依据。", "pos": "术语", "src": "原文"}, {"term": "secondary vocational school", "zh": "中等职业学校", "q": "", "tr": "", "pos": "术语", "src": "原文"}, {"term": "National College Entrance Examination (NCEE)", "zh": "高考", "q": "Secondary vocational education is an alternative to senior middle school. Its objective is to prepare students for careers in production, technical services, management, and other related fields. Afte", "tr": "中等职业教育是高中阶段教育的一种选择。其目标是培养学生从事生产、技术服务、管理及其他相关领域工作的能力。经过三年或四年的学习，毕业生既可以进入自己所学领域的职场就业，也可以参加高考，继续接受高等教育。", "pos": "术语", "src": "原文"}, {"term": "higher education", "zh": "高等教育", "q": "The state implements a school education system that includes preschool, primary, secondary, and higher education. A scientific system of educational grades is established by the state. The establishme", "tr": "国家实行学校教育制度，包括学前教育、初等教育、中等教育和高等教育。国家建立科学的学制系统。该体系内学校及其他教育机构的设立、教育形式、修业年限、招生对象和培养目标，由国务院或国务院授权的教育行政部门规定。", "pos": "术语", "src": "原文"}, {"term": "vocational education", "zh": "职业教育", "q": "Primary schooling is provided for the entire Chinese population. There has also been rapid development in other levels and types of education, such as secondary education, higher education, vocational", "tr": "初等教育面向全体中国人民。中等教育、高等教育、职业教育、特殊教育、成人教育和少数民族教育等其他层次和类型的教育也迅速发展。如今，中国人民拥有比以往任何时候都多的教育机会，可选择的学校和领域也更加广泛。", "pos": "术语", "src": "原文"}, {"term": "adult education", "zh": "成人教育", "q": "Primary schooling is provided for the entire Chinese population. There has also been rapid development in other levels and types of education, such as secondary education, higher education, vocational", "tr": "初等教育面向全体中国人民。中等教育、高等教育、职业教育、特殊教育、成人教育和少数民族教育等其他层次和类型的教育也迅速发展。如今，中国人民拥有比以往任何时候都多的教育机会，可选择的学校和领域也更加广泛。", "pos": "术语", "src": "原文"}, {"term": "special education", "zh": "特殊教育", "q": "Primary schooling is provided for the entire Chinese population. There has also been rapid development in other levels and types of education, such as secondary education, higher education, vocational", "tr": "初等教育面向全体中国人民。中等教育、高等教育、职业教育、特殊教育、成人教育和少数民族教育等其他层次和类型的教育也迅速发展。如今，中国人民拥有比以往任何时候都多的教育机会，可选择的学校和领域也更加广泛。", "pos": "术语", "src": "原文"}, {"term": "education for ethnic minority groups", "zh": "少数民族教育", "q": "Primary schooling is provided for the entire Chinese population. There has also been rapid development in other levels and types of education, such as secondary education, higher education, vocational", "tr": "初等教育面向全体中国人民。中等教育、高等教育、职业教育、特殊教育、成人教育和少数民族教育等其他层次和类型的教育也迅速发展。如今，中国人民拥有比以往任何时候都多的教育机会，可选择的学校和领域也更加广泛。", "pos": "术语", "src": "原文"}, {"term": "international exchanges and cooperation", "zh": "国际交流与合作", "q": "In 1978, one of China’s most significant basic policies, reform and opening up, was adopted. At that point, international exchange and cooperation in education entered a new era. Students were encoura", "tr": "1978年，中国确立了改革开放这一最重要的基本国策之一。自此，教育的国际交流与合作进入新时代。学生被鼓励出国留学，来华留学生人数大幅增加。国际学术交流与合作促进了中国的教育改革与发展，也增进了中国与其他国家之间的相互了解与友谊。", "pos": "术语", "src": "原文"}, {"term": "studying abroad", "zh": "出国留学", "q": "In recent years, an increasing number of students studying abroad have chosen to return and develop their careers domestically. With the solid implementation of more open talent policies, China has be", "tr": "近年来，越来越多的留学生选择回国发展事业。随着更加开放的人才政策扎实实施，中国对海外培养的中国人才越来越具有吸引力。各类回国人才正迅速汇聚，为建设社会主义现代化国家贡献力量。", "pos": "术语", "src": "原文"}, {"term": "international students in China", "zh": "来华留学生", "q": "In 1978, one of China’s most significant basic policies, reform and opening up, was adopted. At that point, international exchange and cooperation in education entered a new era. Students were encoura", "tr": "1978年，中国确立了改革开放这一最重要的基本国策之一。自此，教育的国际交流与合作进入新时代。学生被鼓励出国留学，来华留学生人数大幅增加。国际学术交流与合作促进了中国的教育改革与发展，也增进了中国与其他国家之间的相互了解与友谊。", "pos": "术语", "src": "原文"}, {"term": "academic exchanges and collaboration", "zh": "学术交流与合作", "q": "In 1978, one of China’s most significant basic policies, reform and opening up, was adopted. At that point, international exchange and cooperation in education entered a new era. Students were encoura", "tr": "1978年，中国确立了改革开放这一最重要的基本国策之一。自此，教育的国际交流与合作进入新时代。学生被鼓励出国留学，来华留学生人数大幅增加。国际学术交流与合作促进了中国的教育改革与发展，也增进了中国与其他国家之间的相互了解与友谊。", "pos": "术语", "src": "原文"}, {"term": "Chinese language promotion", "zh": "汉语国际推广", "q": "", "tr": "", "pos": "术语", "src": "原文"}, {"term": "Confucius Institutes", "zh": "孔子学院", "q": "Confucius Institutes are non-profit educational institutions jointly established by Chinese and overseas partner institutions, based on the principles of mutual respect, friendly consultation, equalit", "tr": "孔子学院是由中国与海外合作机构本着相互尊重、友好协商、平等互利的原则共同建立的非营利性教育机构。", "pos": "机构", "src": "原文"}, {"term": "Senior Middle School Graduation Certificate", "zh": "高中毕业证书", "q": "The three-year senior middle school education prepares students for further study at college or university, as well as for entering the workforce or pursuing vocational training. During these three ye", "tr": "高中为三年制，旨在为学生升入大学继续深造，或进入职场、接受职业培训做准备。在这三年中，学生须分阶段参加并通过多个科目的毕业考试，才能获得高中毕业证书。", "pos": "术语", "src": "原文"}, {"term": "Double First-Class", "zh": "双一流", "q": "Launched in 1995, Project 211 is a national initiative in China aimed at strengthening approximately 100 key universities and a number of academic disciplines to enhance their academic standards and g", "tr": "211工程于1995年启动，是中国重点建设约100所高等学校和一批学科、以提高其学术水平和国际竞争力的国家工程。其目标是提高这些高校的教育质量、科研能力和管理水平，使其达到世界一流大学的水平。985工程于1998年启动，旨在重点建设一批世界一流大学和国际知名的高水平研究型大学。该工程是一项提升中国高等教育水平、使其达到世界先进水平的战略举措。在这些工程的基础上，中国继续推进“双一流”建设，着力培育具有中国特色的世界一流大学和一流学科。", "pos": "其他", "src": "原文"}, {"term": "Project Hope", "zh": "希望工程", "q": "The state and society provide various forms of financial assistance to children, adolescents, and youth from economically disadvantaged families who are eligible to attend school. In 1989, China launc", "tr": "国家和社会通过多种形式，向家庭经济困难、符合入学条件的儿童、青少年提供资助。1989年，中国启动了两项公益行动：希望工程和春蕾计划。这两个项目帮助贫困地区的儿童，尤其是女童，得以入学。", "pos": "其他", "src": "原文"}, {"term": "Spring Bud Project", "zh": "春蕾计划", "q": "The state and society provide various forms of financial assistance to children, adolescents, and youth from economically disadvantaged families who are eligible to attend school. In 1989, China launc", "tr": "国家和社会通过多种形式，向家庭经济困难、符合入学条件的儿童、青少年提供资助。1989年，中国启动了两项公益行动：希望工程和春蕾计划。这两个项目帮助贫困地区的儿童，尤其是女童，得以入学。", "pos": "其他", "src": "原文"}, {"term": "the Four Books", "zh": "四书", "q": "• Can you name the Four Books and the Five Classics (“四书五经”)?", "tr": "- 你能说出“四书五经”吗？", "pos": "作品名", "src": "原文"}, {"term": "the Five Classics", "zh": "五经", "q": "• Can you name the Four Books and the Five Classics (“四书五经”)?", "tr": "- 你能说出“四书五经”吗？", "pos": "作品名", "src": "原文"}, {"term": "The Great Learning", "zh": "《大学》", "q": "the Four Books and the Five Classics: The term “Four Books” refers to the four Confucian classics: The Great Learning, The Doctrine of the Mean, The Analects, and Mencius. The term “Five Classics” ref", "tr": "> **四书五经**：“四书”是《大学》《中庸》《论语》《孟子》四部儒家经典的合称；“五经”是《诗》《书》《礼》《易》《春秋》五部儒家经典的合称。", "pos": "作品名", "src": "原文"}, {"term": "The Doctrine of the Mean", "zh": "《中庸》", "q": "the Four Books and the Five Classics: The term “Four Books” refers to the four Confucian classics: The Great Learning, The Doctrine of the Mean, The Analects, and Mencius. The term “Five Classics” ref", "tr": "> **四书五经**：“四书”是《大学》《中庸》《论语》《孟子》四部儒家经典的合称；“五经”是《诗》《书》《礼》《易》《春秋》五部儒家经典的合称。", "pos": "作品名", "src": "原文"}, {"term": "The Analects", "zh": "《论语》", "q": "the Four Books and the Five Classics: The term “Four Books” refers to the four Confucian classics: The Great Learning, The Doctrine of the Mean, The Analects, and Mencius. The term “Five Classics” ref", "tr": "> **四书五经**：“四书”是《大学》《中庸》《论语》《孟子》四部儒家经典的合称；“五经”是《诗》《书》《礼》《易》《春秋》五部儒家经典的合称。", "pos": "作品名", "src": "原文"}, {"term": "Mencius", "zh": "《孟子》", "q": "the Four Books and the Five Classics: The term “Four Books” refers to the four Confucian classics: The Great Learning, The Doctrine of the Mean, The Analects, and Mencius. The term “Five Classics” ref", "tr": "> **四书五经**：“四书”是《大学》《中庸》《论语》《孟子》四部儒家经典的合称；“五经”是《诗》《书》《礼》《易》《春秋》五部儒家经典的合称。", "pos": "作品名", "src": "原文"}, {"term": "The Book of Songs", "zh": "《诗经》", "q": "the Four Books and the Five Classics: The term “Four Books” refers to the four Confucian classics: The Great Learning, The Doctrine of the Mean, The Analects, and Mencius. The term “Five Classics” ref", "tr": "> **四书五经**：“四书”是《大学》《中庸》《论语》《孟子》四部儒家经典的合称；“五经”是《诗》《书》《礼》《易》《春秋》五部儒家经典的合称。", "pos": "作品名", "src": "原文"}, {"term": "The Book of History", "zh": "《尚书》", "q": "the Four Books and the Five Classics: The term “Four Books” refers to the four Confucian classics: The Great Learning, The Doctrine of the Mean, The Analects, and Mencius. The term “Five Classics” ref", "tr": "> **四书五经**：“四书”是《大学》《中庸》《论语》《孟子》四部儒家经典的合称；“五经”是《诗》《书》《礼》《易》《春秋》五部儒家经典的合称。", "pos": "作品名", "src": "原文"}, {"term": "The Book of Rites", "zh": "《礼记》", "q": "the Four Books and the Five Classics: The term “Four Books” refers to the four Confucian classics: The Great Learning, The Doctrine of the Mean, The Analects, and Mencius. The term “Five Classics” ref", "tr": "> **四书五经**：“四书”是《大学》《中庸》《论语》《孟子》四部儒家经典的合称；“五经”是《诗》《书》《礼》《易》《春秋》五部儒家经典的合称。", "pos": "作品名", "src": "原文"}, {"term": "The Book of Changes", "zh": "《易》", "q": "the Four Books and the Five Classics: The term “Four Books” refers to the four Confucian classics: The Great Learning, The Doctrine of the Mean, The Analects, and Mencius. The term “Five Classics” ref", "tr": "> **四书五经**：“四书”是《大学》《中庸》《论语》《孟子》四部儒家经典的合称；“五经”是《诗》《书》《礼》《易》《春秋》五部儒家经典的合称。", "pos": "作品名", "src": "原文"}, {"term": "The Spring and Autumn Annals", "zh": "《春秋》", "q": "the Four Books and the Five Classics: The term “Four Books” refers to the four Confucian classics: The Great Learning, The Doctrine of the Mean, The Analects, and Mencius. The term “Five Classics” ref", "tr": "> **四书五经**：“四书”是《大学》《中庸》《论语》《孟子》四部儒家经典的合称；“五经”是《诗》《书》《礼》《易》《春秋》五部儒家经典的合称。", "pos": "作品名", "src": "原文"}, {"term": "Tsinghua University's Campus", "zh": "清华大学校园", "q": "", "tr": "", "pos": "其他", "src": "原文"}, {"term": "palace examination", "zh": "殿试", "q": "The candidate who won first place in the palace examination was called zhuangyuan (状元), and he would be granted a high-ranking position in the court. The one who won second place was called bangyan (榜", "tr": "在殿试中夺得第一名的考生称为状元，会被授予朝廷的高位。第二名称为榜眼，第三名称为探花。他们也都会被委以政府的重要职位。", "pos": "术语", "src": "原文"}, {"term": "eight-part essay", "zh": "八股文", "q": "During the Ming and Qing dynasties, participants in the imperial civil examinations were required to write essays in strict accordance with an eight-part form, which was known for its rigidity of stru", "tr": "明清时期，科举考生必须严格按照八股文的形式作文，八股文以结构僵化、严守统治阶级思想而著称。新的思想常常受到排斥。人们认为，科举在内容和形式上的僵化，在一定程度上束缚了人们的思想，限制了文化的进步。", "pos": "术语", "src": "原文"}, {"term": "military examination", "zh": "武举", "q": "During the Ming and Qing dynasties, the imperial civil examination was held once every three years. It featured composition writing, which was designed to select jinshi (进士), the successful candidates", "tr": "明清时期，科举每三年举行一次。科举设有以文取士的写作考试，用以选拔进士，即在最高一级科举考试中及第者。武举则侧重武艺，包括马术、射箭和举重。", "pos": "术语", "src": "原文"}, {"term": "Confucius", "zh": "孔子", "q": "During the Spring and Autumn Period, private schools began to emerge, and many scholars of different schools of thought spread their teachings through private instruction. Among them, Confucius’s priv", "tr": "春秋时期，私学开始兴起，诸子百家的许多学者都通过私人讲学来传播自己的学说。其中，孔子的私人讲学影响最大、流传最广。孔子毕生致力于教育，教授了许多学生。相传他有弟子三千，其中七十二人尤为杰出，后来都成为儒家学说的传播者。", "pos": "人物", "src": "原文"}, {"term": "Daoism", "zh": "道家", "q": "Thoughts of other schools, such as Daoism, were also widely taught, contributing to “the contention of a hundred schools of thought”. Throughout many dynasties, private schools flourished alongside of", "tr": "道家等其他学派的思想也得到广泛传授，促成了“百家争鸣”的局面。历经多个朝代，私学与官学并行而兴，共同繁荣。", "pos": "术语", "src": "原文"}, {"term": "the contention of a hundred schools of thought", "zh": "百家争鸣", "q": "Thoughts of other schools, such as Daoism, were also widely taught, contributing to “the contention of a hundred schools of thought”. Throughout many dynasties, private schools flourished alongside of", "tr": "道家等其他学派的思想也得到广泛传授，促成了“百家争鸣”的局面。历经多个朝代，私学与官学并行而兴，共同繁荣。", "pos": "术语", "src": "原文"}, {"term": "Spring and Autumn Period", "zh": "春秋时期", "q": "During the Spring and Autumn Period, private schools began to emerge, and many scholars of different schools of thought spread their teachings through private instruction. Among them, Confucius’s priv", "tr": "春秋时期，私学开始兴起，诸子百家的许多学者都通过私人讲学来传播自己的学说。其中，孔子的私人讲学影响最大、流传最广。孔子毕生致力于教育，教授了许多学生。相传他有弟子三千，其中七十二人尤为杰出，后来都成为儒家学说的传播者。", "pos": "朝代", "src": "原文"}, {"term": "Western Zhou Dynasty", "zh": "西周", "q": "During the Western Zhou Dynasty, official schools flourished. These schools primarily admitted children of the nobility. The official schooling system included a central school and local schools in di", "tr": "西周时期，官学兴盛。这些学校主要招收贵族子弟。官学体系包括中央官学和设于不同行政区域的地方官学。教学内容以“四书五经”等经典文本为主。隋唐以后，官学开始对学生的年龄和学习年限作出一定限制，允许少数学生修满规定的学业年限后直接授官。然而，对大多数读书人而言，科举仍是进入仕途的必由之路。", "pos": "朝代", "src": "原文"}, {"term": "Han Dynasty", "zh": "汉朝", "q": "The origins of higher education in China are a subject of scholarly debate. Some historians trace its beginnings to the Western Zhou Dynasty, while others point to the Taixue (太学) of the Han Dynasty. ", "tr": "中国高等教育的起源是学界争论的话题。一些历史学家将其开端追溯到西周，另一些则指向汉代的太学。汉朝政府设立太学，作为培养高级人才、协助管理国家事务的最高学府。自隋朝起，高等教育机构改称国子监。它既是全国最高学府，也是负责管理教育的行政机构。", "pos": "朝代", "src": "原文"}, {"term": "Sui Dynasty", "zh": "隋朝", "q": "The imperial civil examination system dominated education in China’s feudal society. It became the primary method through which talented individuals were recognised and appointed as government officia", "tr": "科举制度在中国封建社会中居于主导地位。它成为识别人才并授予官职的主要途径。科举始于隋朝，一直延续到清末，前后约1300年。它对隋唐以后中国的社会结构、政治制度、教育制度和人文思想都产生了深远影响。", "pos": "朝代", "src": "原文"}, {"term": "Tang Dynasty", "zh": "唐朝", "q": "Classical academies came into being during the Tang Dynasty and continued until the end of the Qing Dynasty. They were established in various localities for teaching, research, and book collection. In", "tr": "书院产生于唐朝，一直延续到清末。书院设于各地，用于讲学、研究和藏书。书院独立于官学之外，往往坐落于清幽秀美的环境之中，崇尚学术自由与创新，注重人格的养成。书院对古代中国教育和文化的发展产生了深远影响，并在向海外传播中国文化方面发挥了重要作用。", "pos": "朝代", "src": "原文"}, {"term": "Song Dynasty", "zh": "宋朝", "q": "", "tr": "", "pos": "朝代", "src": "原文"}, {"term": "Ming and Qing dynasties", "zh": "明清", "q": "During the Ming and Qing dynasties, the imperial civil examination was held once every three years. It featured composition writing, which was designed to select jinshi (进士), the successful candidates", "tr": "明清时期，科举每三年举行一次。科举设有以文取士的写作考试，用以选拔进士，即在最高一级科举考试中及第者。武举则侧重武艺，包括马术、射箭和举重。", "pos": "朝代", "src": "原文"}, {"term": "Qing Dynasty", "zh": "清朝", "q": "Classical academies came into being during the Tang Dynasty and continued until the end of the Qing Dynasty. They were established in various localities for teaching, research, and book collection. In", "tr": "书院产生于唐朝，一直延续到清末。书院设于各地，用于讲学、研究和藏书。书院独立于官学之外，往往坐落于清幽秀美的环境之中，崇尚学术自由与创新，注重人格的养成。书院对古代中国教育和文化的发展产生了深远影响，并在向海外传播中国文化方面发挥了重要作用。", "pos": "朝代", "src": "原文"}, {"term": "Revolution of 1911", "zh": "辛亥革命", "q": "New Learning refers to the political ideas and academic culture introduced into China from the West before the May Fourth Movement, and it is in contrast to the traditional Chinese ideological and cul", "tr": "新学指五四运动以前从西方传入中国的政治思想和学术文化，与被称为“旧学”的中国传统思想文化观念相对。辛亥革命后，中国引入了涵盖从小学到大学各级的学校教育制度。", "pos": "事件", "src": "原文"}, {"term": "May Fourth Movement", "zh": "五四运动", "q": "New Learning refers to the political ideas and academic culture introduced into China from the West before the May Fourth Movement, and it is in contrast to the traditional Chinese ideological and cul", "tr": "新学指五四运动以前从西方传入中国的政治思想和学术文化，与被称为“旧学”的中国传统思想文化观念相对。辛亥革命后，中国引入了涵盖从小学到大学各级的学校教育制度。", "pos": "事件", "src": "原文"}, {"term": "Compulsory Education Law of the People's Republic of China", "zh": "《中华人民共和国义务教育法》", "q": "The Compulsory Education Law of the People’s Republic of China came into effect on 1st July 1986, requiring all children to complete nine years of formal education. The nine-year compulsory education ", "tr": "《中华人民共和国义务教育法》于1986年7月1日起施行，要求所有儿童完成九年正规教育。九年义务教育由小学和初中两个阶段组成。", "pos": "作品名", "src": "原文"}, {"term": "compulsory education", "zh": "义务教育", "q": "The Compulsory Education Law of the People’s Republic of China came into effect on 1st July 1986, requiring all children to complete nine years of formal education. The nine-year compulsory education ", "tr": "《中华人民共和国义务教育法》于1986年7月1日起施行，要求所有儿童完成九年正规教育。九年义务教育由小学和初中两个阶段组成。", "pos": "术语", "src": "原文"}, {"term": "kindergarten", "zh": "幼儿园", "q": "Kindergartens are generally staffed with teachers, principals, caregivers, and healthcare personnel. China has formulated regulations regarding the qualifications and performance assessment of kinderg", "tr": "幼儿园一般配备教师、园长、保育员和卫生保健人员。中国制定了关于幼儿园教师资质和考核的规定，幼儿园教师须接受学前教育的正规培训。", "pos": "术语", "src": "原文"}, {"term": "academic proficiency examination", "zh": "学业水平考试", "q": "In China, generally, all children who reach the age of six are required to enter primary school. In areas where conditions are not adequate, children may start school at seven. Primary school graduate", "tr": "在中国，凡年满6周岁的儿童一般都应入小学就读。条件不具备的地区，儿童可推迟到7岁入学。小学毕业生可免试升入初中。初中毕业后，学生可以选择就读职业学校，或升入高中继续接受普通教育。初中学生在最后一年参加学业水平考试。该考试成绩有两个重要作用：判定学生是否达到毕业要求，以及作为升入高中的依据。", "pos": "术语", "src": "原文"}, {"term": "privately run schools", "zh": "民办学校", "q": "A sishu (私塾) was a type of private educational institution in ancient China, typically established within families or villages to provide early childhood education. These privately run schools formed ", "tr": "私塾是中国古代的一种私人教育机构，通常设于家族或乡村之中，为儿童提供启蒙教育。这类私人开办的学校构成了传统私学体系的重要组成部分。", "pos": "术语", "src": "原文"}, {"term": "system of educational grades", "zh": "学制", "q": "The state implements a school education system that includes preschool, primary, secondary, and higher education. A scientific system of educational grades is established by the state. The establishme", "tr": "国家实行学校教育制度，包括学前教育、初等教育、中等教育和高等教育。国家建立科学的学制系统。该体系内学校及其他教育机构的设立、教育形式、修业年限、招生对象和培养目标，由国务院或国务院授权的教育行政部门规定。", "pos": "术语", "src": "原文"}, {"term": "reinvigorate the nation through science and education", "zh": "科教兴国", "q": "China is fully implementing strategies to reinvigorate the nation through science, education, and human resource development. Its goal is to build an education system that meets the needs and expectat", "tr": "中国全面实施科教兴国战略和人才强国战略，目标是构建一个满足全体人民需要和期盼的教育体系。", "pos": "术语", "src": "原文"}, {"term": "human resource development strategy", "zh": "人才强国", "q": "China is fully implementing strategies to reinvigorate the nation through science, education, and human resource development. Its goal is to build an education system that meets the needs and expectat", "tr": "中国全面实施科教兴国战略和人才强国战略，目标是构建一个满足全体人民需要和期盼的教育体系。", "pos": "术语", "src": "原文"}, {"term": "modern socialist country", "zh": "社会主义现代化国家", "q": "In recent years, an increasing number of students studying abroad have chosen to return and develop their careers domestically. With the solid implementation of more open talent policies, China has be", "tr": "近年来，越来越多的留学生选择回国发展事业。随着更加开放的人才政策扎实实施，中国对海外培养的中国人才越来越具有吸引力。各类回国人才正迅速汇聚，为建设社会主义现代化国家贡献力量。", "pos": "术语", "src": "原文"}, {"term": "Chinese-foreign cooperation in running schools", "zh": "中外合作办学", "q": "Today, China is taking more action to expand high-level opening up. More Chinese-foreign cooperation in running schools is strengthening higher education and vocational education, and more high-qualit", "tr": "如今，中国正采取更多措施扩大高水平对外开放。越来越多的中外合作办学增强了高等教育和职业教育，更多优质的外国教育资源被引入。", "pos": "术语", "src": "原文"}, {"term": "Chinese-Plus cloud platform", "zh": "“中文+”云平台", "q": "By the end of 2020, more than 180 countries and regions around the world had launched Chinese language education programmes, with more than 70 countries incorporating Chinese into their national educa", "tr": "截至2020年底，全球已有180多个国家和地区开展中文教育，70多个国家将中文纳入国民教育体系。此后，学习中文的外国人数已超过2000万。在线中文教育也蓬勃发展。例如，“中文+”云平台〔译者注：原文为“Chinese-Plus” cloud platform，具体平台名待核〕为202个国家和地区的用户提供优质资源，向1000多万注册用户提供3万多门在线课程。中文的国际地位不断提升，2021年，中文正式成为联合国世界旅游组织的官方语言之一。", "pos": "术语", "src": "原文"}, {"term": "reform and opening up", "zh": "改革开放", "q": "In 1978, one of China’s most significant basic policies, reform and opening up, was adopted. At that point, international exchange and cooperation in education entered a new era. Students were encoura", "tr": "1978年，中国确立了改革开放这一最重要的基本国策之一。自此，教育的国际交流与合作进入新时代。学生被鼓励出国留学，来华留学生人数大幅增加。国际学术交流与合作促进了中国的教育改革与发展，也增进了中国与其他国家之间的相互了解与友谊。", "pos": "术语", "src": "原文"}, {"term": "Project 211", "zh": "211工程", "q": "Launched in 1995, Project 211 is a national initiative in China aimed at strengthening approximately 100 key universities and a number of academic disciplines to enhance their academic standards and g", "tr": "211工程于1995年启动，是中国重点建设约100所高等学校和一批学科、以提高其学术水平和国际竞争力的国家工程。其目标是提高这些高校的教育质量、科研能力和管理水平，使其达到世界一流大学的水平。985工程于1998年启动，旨在重点建设一批世界一流大学和国际知名的高水平研究型大学。该工程是一项提升中国高等教育水平、使其达到世界先进水平的战略举措。在这些工程的基础上，中国继续推进“双一流”建设，着力培育具有中国特色的世界一流大学和一流学科。", "pos": "其他", "src": "原文"}, {"term": "Project 985", "zh": "985工程", "q": "Launched in 1995, Project 211 is a national initiative in China aimed at strengthening approximately 100 key universities and a number of academic disciplines to enhance their academic standards and g", "tr": "211工程于1995年启动，是中国重点建设约100所高等学校和一批学科、以提高其学术水平和国际竞争力的国家工程。其目标是提高这些高校的教育质量、科研能力和管理水平，使其达到世界一流大学的水平。985工程于1998年启动，旨在重点建设一批世界一流大学和国际知名的高水平研究型大学。该工程是一项提升中国高等教育水平、使其达到世界先进水平的战略举措。在这些工程的基础上，中国继续推进“双一流”建设，着力培育具有中国特色的世界一流大学和一流学科。", "pos": "其他", "src": "原文"}, {"term": "UNESCO", "zh": "联合国教科文组织", "q": "High-level cultural and educational exchanges have gathered momentum in recent years. China’s partnership with UNESCO began a new chapter through China’s further participation in international program", "tr": "近年来，高层次的文化和教育交流势头强劲。通过进一步参与教育、科学和文化领域的国际项目，中国与联合国教科文组织的合作翻开了新篇章。中国政府积极参与和支持联合国教科文组织的重大倡议，搭建高水平教育合作的全球平台，为全球教育治理作出贡献。", "pos": "机构", "src": "原文"}, {"term": "United Nations World Tourism Organization", "zh": "联合国世界旅游组织", "q": "By the end of 2020, more than 180 countries and regions around the world had launched Chinese language education programmes, with more than 70 countries incorporating Chinese into their national educa", "tr": "截至2020年底，全球已有180多个国家和地区开展中文教育，70多个国家将中文纳入国民教育体系。此后，学习中文的外国人数已超过2000万。在线中文教育也蓬勃发展。例如，“中文+”云平台〔译者注：原文为“Chinese-Plus” cloud platform，具体平台名待核〕为202个国家和地区的用户提供优质资源，向1000多万注册用户提供3万多门在线课程。中文的国际地位不断提升，2021年，中文正式成为联合国世界旅游组织的官方语言之一。", "pos": "机构", "src": "原文"}, {"term": "State Council", "zh": "国务院", "q": "The state implements a school education system that includes preschool, primary, secondary, and higher education. A scientific system of educational grades is established by the state. The establishme", "tr": "国家实行学校教育制度，包括学前教育、初等教育、中等教育和高等教育。国家建立科学的学制系统。该体系内学校及其他教育机构的设立、教育形式、修业年限、招生对象和培养目标，由国务院或国务院授权的教育行政部门规定。", "pos": "机构", "src": "原文"}, {"term": "People's Republic of China", "zh": "中华人民共和国", "q": "Since 1949, when the People’s Republic of China was founded, education has been a top priority. The government emphasises protecting the educational rights of its population, especially for ethnic min", "tr": "自1949年中华人民共和国成立以来，教育一直处于优先地位。政府重视保障人民群众的受教育权，尤其是少数民族、儿童、妇女和残疾人的受教育权。经过数十年的不懈努力，中国在教育方面取得了显著进步。", "pos": "机构", "src": "原文"}, {"term": "Yuelu Academy", "zh": "岳麓书院", "q": "There were four famous academies in ancient China: Yuelu Academy in Changsha, Hunan Province; Bailudong Academy in Jiujiang, Jiangxi Province; Songyang Academy in Zhengzhou, Henan Province; and Yingti", "tr": "中国古代有四大著名书院：湖南长沙的岳麓书院、江西九江的白鹿洞书院、河南郑州的嵩阳书院和河南商丘的应天书院。", "pos": "机构", "src": "原文"}, {"term": "Bailudong Academy", "zh": "白鹿洞书院", "q": "There were four famous academies in ancient China: Yuelu Academy in Changsha, Hunan Province; Bailudong Academy in Jiujiang, Jiangxi Province; Songyang Academy in Zhengzhou, Henan Province; and Yingti", "tr": "中国古代有四大著名书院：湖南长沙的岳麓书院、江西九江的白鹿洞书院、河南郑州的嵩阳书院和河南商丘的应天书院。", "pos": "机构", "src": "原文"}, {"term": "Songyang Academy", "zh": "嵩阳书院", "q": "There were four famous academies in ancient China: Yuelu Academy in Changsha, Hunan Province; Bailudong Academy in Jiujiang, Jiangxi Province; Songyang Academy in Zhengzhou, Henan Province; and Yingti", "tr": "中国古代有四大著名书院：湖南长沙的岳麓书院、江西九江的白鹿洞书院、河南郑州的嵩阳书院和河南商丘的应天书院。", "pos": "机构", "src": "原文"}, {"term": "Yingtian Academy", "zh": "应天书院", "q": "There were four famous academies in ancient China: Yuelu Academy in Changsha, Hunan Province; Bailudong Academy in Jiujiang, Jiangxi Province; Songyang Academy in Zhengzhou, Henan Province; and Yingti", "tr": "中国古代有四大著名书院：湖南长沙的岳麓书院、江西九江的白鹿洞书院、河南郑州的嵩阳书院和河南商丘的应天书院。", "pos": "机构", "src": "原文"}], "vocabB": [], "examsA": [{"term": "", "zh": "", "cn": "为了促进教育公平，中国已投入 360 亿元,用于改善农村地区教育设施和加强中西部地区农村义务教育(compulsory education)。", "en": "To promote educational equity, China has invested 36 billion yuan to improve educational facilities in rural areas and strengthen compulsory education in rural areas of the central and western regions.", "ptype": "真题", "cat": "真题A", "map": "教育公平与农村义务教育", "set": "CET4 2014·06·S3", "src": "CET4 2014·06·S3", "cls": "Chapter 4", "tip": "断句:分句①\"为了促进教育公平\"/②\"中国已投入360亿元\"/③\"用于改善…和加强…\";核心=②;①→目的状语(To promote…)(CL-07);③→目的状语(to improve… and strengthen…)|for V-ing;时锚:已投入→现在完成时;话题:补主语(→China);文化:教育公平→S1 educational equity(库)；农村义务教育→S1 compulsory education(原卷括注 compulsory education，同源优先)；中西部地区→S1 the central and western regions(库)；备注:[原卷如此]（\"亿元,用于\"处为半角逗号，照抄不改）", "ta": "补主语（话题→主语，Li & Thompson 1976）；目的状语前置（连淑能 1993）；时态呼应（现在完成时，连淑能 1993）。", "te": "增补（To / to 引出目的，Amplification，Molina & Albir 2002）；数字转换（\"360 亿元\"→36 billion yuan）；词性转换（\"教育设施\"→educational facilities）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"教育公平\"对应官方短语见中国政府网英文版（\"Ensuring educational equity…\"，S1）；\"义务教育\"见教育部英文网（S1）；\"中西部地区\"见中国政府网英文版（S1）；\"农村义务教育\"取库内 compulsory education in rural areas（成分级，S1）。", "rp": "`invest … in / invest … to V`（L2·PC）；`improve … and strengthen …`（L2·PC）；`To V …, 主句`（目的，CL-07）（L2·SB）→ 本句实例：To promote educational equity, China has invested …。"}, {"term": "", "zh": "", "cn": "这些资金用于改善教学设施、购买书籍，使 16 万多所中小学受益。", "en": "These funds are used to improve school equipment and facilities and to purchase books, benefiting more than 160,000 primary and secondary schools.", "ptype": "真题", "cat": "真题A", "map": "教育公平与农村义务教育", "set": "CET4 2014·06·S3", "src": "CET4 2014·06·S3", "cls": "Chapter 4", "tip": "断句:分句①\"资金用于改善教学设施、购买书籍\"/②\"使16万多所中小学受益\";核心=①;②→结果状语(V-ing benefiting…)|so that…;时锚:一般现在时(陈述用途);话题:补主语(→These funds);文化:教学设施→S1 school equipment and facilities(库)；中小学→S1 primary and secondary schools(库)", "ta": "补主语；受事主语→被动（are used to，CL-04）；分词状语（benefiting…，连淑能 1993）。", "te": "增补（more than）；动词并列（\"改善…、购买…\"→improve… and to purchase…）；数字表达（\"16 万多所\"→more than 160,000）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"教学设施\"见教育部英文网（S1）；\"中小学\"见教育部英文网（S1）；\"农村地区\"见教育部英文网（S1）。", "rp": "`be used to V`（L2·PC）；`V-ing 状语`（L2·SB）→ 本句实例：…, benefiting more than 160,000 primary and secondary schools。"}, {"term": "", "zh": "", "cn": "资金还用于购置音乐和绘画器材。", "en": "The funds are also used to purchase music and painting equipment.", "ptype": "真题", "cat": "真题A", "map": "教育公平与农村义务教育", "set": "CET4 2014·06·S3", "src": "CET4 2014·06·S3", "cls": "Chapter 4", "tip": "断句:单分句;核心=①;时锚:一般现在时;话题:补主语(→The funds，承前指代);文化:音乐和绘画器材→musical and painting equipment(S4 通译)", "ta": "补主语＋定冠词回指（连淑能 1993）；受事→被动（CL-04）。", "te": "增补（also）；词性转换（\"购置\"→purchase）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`be used to purchase`（L2·PC）。"}, {"term": "", "zh": "", "cn": "现在农村和山区的儿童可以与沿海城市的儿童一样上音乐和绘画课。", "en": "Today, children in rural and mountainous areas can take music and painting classes just like children in coastal cities.", "ptype": "真题", "cat": "真题A", "map": "教育公平与农村义务教育", "set": "CET4 2014·06·S3", "src": "CET4 2014·06·S3", "cls": "Chapter 4", "tip": "断句:单分句;核心=①;时锚:现在→一般现在时;话题:补主语(→children);逻辑:比较对照→just like / as … as;文化:山区→mountainous areas；沿海城市→coastal cities", "ta": "补主语；时间状语前置（连淑能 1993）；意合→形合（比较对照显性化，连淑能 1993）。", "te": "增补（Today / just）；词性转换（\"上…课\"→take … classes）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`just like`（对照，L2·PC）；`take … classes`（L2·PC）。"}, {"term": "", "zh": "", "cn": "一些为接受更好教育而转往城市上学的学生如今又回到了本地农村学校就读。", "en": "Some students who moved to cities for a better education have now returned to their local rural schools.", "ptype": "真题", "cat": "真题A", "map": "教育公平与农村义务教育", "set": "CET4 2014·06·S3", "src": "CET4 2014·06·S3", "cls": "Chapter 4", "tip": "断句:单分句;核心=①;时锚:如今→一般现在时|现在完成时（\"又回到了\"→have returned）;话题:补主语(→some students);修饰:\"为接受更好教育而转往城市上学的\"→定语从句(who moved to cities for a better education)后置;文化:本地农村学校→their local rural schools", "ta": "补主语；修饰语后置（\"转往城市上学的\"→who moved to cities，连淑能 1993）；时态呼应（现在完成时，连淑能 1993）。", "te": "增补（now / their）；动词转译（\"就读\"→returned to … schools）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`return to`（L2·PC）；`for a better education`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国家庭十分重视孩子的教育。", "en": "Chinese families attach great importance to their children's education.", "ptype": "真题", "cat": "真题A", "map": "家庭教育与教育投入", "set": "CET4 2019·12·S1", "src": "CET4 2019·12·S1", "cls": "Chapter 4", "tip": "断句:单分句;核心=①;话题:补主语(→Chinese families);文化:重视→S1 attach great importance to(库)", "ta": "补主语（话题→主语，Li & Thompson 1976）。", "te": "惯用等值（\"重视\"→attach great importance to）；增补（their）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"高度重视（+N）\"对应官方短语见 China Daily / 官方英文站（attach great importance to，S1）。", "rp": "`attach great importance to`（L2·PC）。"}, {"term": "", "zh": "", "cn": "许多父母认为应该努力工作，确保孩子受到良好教育。", "en": "Many parents believe that they should work hard to ensure that their children receive a good education.", "ptype": "真题", "cat": "真题A", "map": "家庭教育与教育投入", "set": "CET4 2019·12·S1", "src": "CET4 2019·12·S1", "cls": "Chapter 4", "tip": "断句:分句①\"认为应该努力工作\"/②\"确保孩子受到良好教育\";核心=①;②→目的状语(to ensure…)|宾语从句;话题:补主语(→Many parents);文化:受到良好教育→receive a good education", "ta": "补主语；意合→形合（②→that 宾语从句＋目的 to ensure，连淑能 1993）。", "te": "增补（that / their）；受事→主动转译（\"受到良好教育\"→receive a good education）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`believe that …`（L2·SB）→ 本句实例：Many parents believe that they should work hard…；`ensure that …`（L2·PC）。"}, {"term": "", "zh": "", "cn": "他们不仅非常情愿为孩子的教育投资，而且花很多时间督促他们学习。", "en": "They are not only very willing to invest in their children's education but also spend a lot of time urging them to study.", "ptype": "真题", "cat": "真题A", "map": "家庭教育与教育投入", "set": "CET4 2019·12·S1", "src": "CET4 2019·12·S1", "cls": "Chapter 4", "tip": "断句:分句①②;核心=并列;触发[不仅…而且]→not only … but also …;话题:补主语(→They);文化:为…投资→invest in …；督促→urge / push", "ta": "补主语；触发构式（not only…but also…，认知构式翻译观）。", "te": "增补（very / a lot of）；动词转译（\"督促\"→urging）；词性转换（\"情愿\"→willing）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`not only … but also …`（L2·SB）→ 本句实例：They are not only very willing to invest… but also spend a lot of time…；`invest in`（L2·PC）；`urge sb to V`（L2·PC）。"}, {"term": "", "zh": "", "cn": "多数家长希望孩子能上名牌大学。", "en": "Most parents hope that their children can attend prestigious universities.", "ptype": "真题", "cat": "真题A", "map": "家庭教育与教育投入", "set": "CET4 2019·12·S1", "src": "CET4 2019·12·S1", "cls": "Chapter 4", "tip": "断句:单分句;核心=①;话题:补主语(→Most parents);文化:名牌大学→prestigious universities(S4 通译)", "ta": "补主语；意合→形合（→that 宾语从句，连淑能 1993）。", "te": "增补（their）；动词转译（\"上（大学）\"→attend）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"名牌大学\"无白名单定译，标 S4（elite / top universities 并存）。", "rp": "`hope that …`（L2·SB）→ 本句实例：Most parents hope that their children can attend…；`attend a university`（L2·PC）。"}, {"term": "", "zh": "", "cn": "由于改革开放，越来越多的家长能送孩子到国外学习或参与国际交流项目，以拓宽其视野。", "en": "Thanks to reform and opening up, more and more parents are able to send their children to study abroad or take part in international exchange programs to broaden their horizons.", "ptype": "真题", "cat": "真题A", "map": "家庭教育与教育投入", "set": "CET4 2019·12·S1", "src": "CET4 2019·12·S1", "cls": "Chapter 4", "tip": "断句:分句①\"由于改革开放\"/②\"越来越多家长能送孩子到国外学习或参与国际交流项目\"/③\"以拓宽其视野\";核心=②;①→原因状语(Thanks to…|Because of…);③→目的状语(to broaden their horizons);动力:补主语(→more and more parents);文化:改革开放→S1 reform and opening up(库定译)；国际交流项目→international exchange programs；拓宽视野→broaden their horizons", "ta": "补主语；原因状语前置（连淑能 1993）；目的状语化（to broaden…，连淑能 1993）。", "te": "增补（Thanks to / to）；惯用等值（\"拓宽视野\"→broaden their horizons）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"改革开放\"对应官方定译见官方英文站（reform and opening up，S1）；\"增长见识、开阔视野\"见库（broaden one's horizons，S4 通译）。", "rp": "`be able to V`（L2·PC）；`send sb to do sth`（L2·PC）；`broaden one's horizons`（L2·PC）。"}, {"term": "", "zh": "", "cn": "通过这些努力，他们期望孩子健康成长，为国家的发展和繁荣作出贡献。", "en": "Through these efforts, they expect their children to grow up healthy and make contributions to the development and prosperity of the country.", "ptype": "真题", "cat": "真题A", "map": "家庭教育与教育投入", "set": "CET4 2019·12·S1", "src": "CET4 2019·12·S1", "cls": "Chapter 4", "tip": "断句:单分句;核心=①\"他们期望…\";话题:补主语(→they);逻辑:方式状语(Through these efforts);文化:国家的发展和繁荣→the development and prosperity of the country；作出贡献→make contributions to", "ta": "补主语；方式状语前置（连淑能 1993）。", "te": "增补（Through…）；词性转换（\"健康成长\"→grow up healthy）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`expect sb to V`（L2·PC）；`make contributions to`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国政府一直大力推行义务教育(compulsory education)，以使每个儿童都享有受教育的机会。", "en": "The Chinese government has been actively promoting compulsory education to ensure that every child has access to education.", "ptype": "真题", "cat": "真题A", "map": "义务教育", "set": "CET4 2023·06·S1", "src": "CET4 2023·06·S1", "cls": "Chapter 4", "tip": "断句:分句①\"政府推行义务教育\"/②\"以使每个儿童享有受教育机会\";核心=①;②→目的状语(so that…|to ensure…);时锚:一直→现在完成进行时|现在完成时;话题:补主语(→The Chinese government);文化:义务教育→S1 compulsory education(原卷括注，同源优先)", "ta": "补主语；目的状语化（to ensure…，连淑能 1993）；时态呼应（现在完成进行时，连淑能 1993）。", "te": "增补（actively）；惯用等值（\"享有…机会\"→have access to）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"义务教育\"见教育部英文网（compulsory education，S1）；\"中国政府\"见 China Daily（the Chinese government，S1）。", "rp": "`have access to`（L2·PC）；`ensure that …`（L2·PC）；`to ensure …`（目的，L2·SB）→ 本句实例：… promoting compulsory education to ensure that every child has access to education。"}, {"term": "", "zh": "", "cn": "自 1986 年《义务教育法》生效以来，经过不懈努力，实现了在全国推行义务教育的目标。", "en": "Since the Compulsory Education Law came into effect in 1986, China has achieved the goal of implementing compulsory education nationwide through unremitting efforts.", "ptype": "真题", "cat": "真题A", "map": "义务教育", "set": "CET4 2023·06·S1", "src": "CET4 2023·06·S1", "cls": "Chapter 4", "tip": "断句:分句①\"自1986年《义务教育法》生效以来\"/②\"经过不懈努力\"/③\"实现了在全国推行义务教育的目标\";核心=③;①→时间状语从句(Since…came into effect);②→方式状语(through unremitting efforts);话题:无主句→补主语(China)|受事→被动;时锚:自…以来→现在完成时;文化:《义务教育法》→Compulsory Education Law(教材术语库)；在全国推行→implement nationwide", "ta": "时间状语从句前置（连淑能 1993）；补主语（无主句→China）；时态呼应（现在完成时，连淑能 1993）。", "te": "增补（Since / through）；词性转换（\"生效\"→came into effect；\"推行\"→implementing）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"《中华人民共和国义务教育法》\"教材定译 Compulsory Education Law of the People's Republic of China（教材术语库），S1。", "rp": "`come into effect`（L2·PC）；`achieve the goal of V-ing`（L2·PC）；`Since …, 主句`（L2·SB）→ 本句实例：Since the Compulsory Education Law came into effect in 1986, China has achieved…。"}, {"term": "", "zh": "", "cn": "如今，在中国，儿童年满六周岁开始上小学，从小学到初中一共接受九年义务教育。", "en": "Today in China, children start primary school at the age of six and receive nine years of compulsory education from primary school to junior middle school.", "ptype": "真题", "cat": "真题A", "map": "义务教育", "set": "CET4 2023·06·S1", "src": "CET4 2023·06·S1", "cls": "Chapter 4", "tip": "断句:分句①②;核心=①;②→并列;时锚:如今→一般现在时;话题:补主语(→children);文化:年满六周岁→at the age of six；小学→primary school；初中→junior middle school；九年义务教育→nine-year compulsory education(教材定译 Nine-Year Compulsory Education)", "ta": "补主语；时间/地点状语前置（连淑能 1993）；意合→形合（并列 and，连淑能 1993）。", "te": "增补（at the age of / from…to…）；词性转换（\"年满六周岁\"→at the age of six）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"九年义务教育\"教材定译 Nine-Year Compulsory Education（教材术语库），S1。", "rp": "`at the age of`（L2·PC）；`from … to …`（L2·SB）→ 本句实例：… from primary school to junior middle school。"}, {"term": "", "zh": "", "cn": "从 2008 年秋季学期开始，义务教育阶段学生无需缴纳学费。", "en": "Starting from the autumn semester of 2008, students in the compulsory education stage no longer need to pay tuition fees.", "ptype": "真题", "cat": "真题A", "map": "义务教育", "set": "CET4 2023·06·S1", "src": "CET4 2023·06·S1", "cls": "Chapter 4", "tip": "断句:单分句;核心=①;时锚:从2008年秋季学期开始→一般过去时|现在完成时;话题:补主语(→students);受事→主动转译;文化:秋季学期→the autumn semester；缴纳学费→pay tuition fees", "ta": "补主语；时间状语前置（连淑能 1993）。", "te": "增补（Starting from / no longer）；词性转换（\"无需缴纳\"→no longer need to pay）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`starting from`（L2·PC）；`no longer need to V`（L2·PC）。"}, {"term": "", "zh": "", "cn": "随着一系列教育改革举措的实施，中国义务教育的质量也有显著提高。", "en": "With the implementation of a series of education reform measures, the quality of China's compulsory education has also improved significantly.", "ptype": "真题", "cat": "真题A", "map": "义务教育", "set": "CET4 2023·06·S1", "src": "CET4 2023·06·S1", "cls": "Chapter 4", "tip": "断句:单分句;核心=①;①→伴随状语(With the implementation of…)|As…;触发[随着]→with + n.|as + 从句;时锚:一般现在时|现在完成时(has improved);话题:补主语(→the quality of China's compulsory education);文化:教育改革→education reform", "ta": "伴随状语前置（with＋名词，连淑能 1993）；补主语；时态呼应（现在完成时，连淑能 1993）。", "te": "名词化（\"实施\"→implementation；\"提高\"→improved）；增补（a series of / also）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"义务教育\"见教育部英文网（S1）。", "rp": "`with the implementation of`（L2·PC）；`improve significantly`（L2·PC）。"}, {"term": "", "zh": "", "cn": "改革开放 40 多年以来，中国政府对高等教育越来越重视，高等教育已经进入稳步发展阶段。", "en": "Over more than 40 years of reform and opening up, the Chinese government has attached increasing importance to higher education, and higher education has entered a stage of steady development.", "ptype": "真题", "cat": "真题A", "map": "高等教育", "set": "CET4 2023·06·S2", "src": "CET4 2023·06·S2", "cls": "Chapter 4", "tip": "断句:分句①②;核心=①|②并列;①→时间状语(Over more than 40 years of…)|Since…;时锚:以来/已经→现在完成时;话题:补主语(→The Chinese government / higher education);文化:改革开放→S1 reform and opening up(库定译)；高等教育→S1 higher education(教材定译)", "ta": "补主语；时间状语前置（连淑能 1993）；意合→形合（并列 and，连淑能 1993）；时态呼应（现在完成时，连淑能 1993）。", "te": "增补（Over more than）；词性转换（\"重视\"→attached importance to；\"稳步发展\"→steady development）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"改革开放\"见官方英文站（reform and opening up，S1）；\"高等教育\"教材定译 higher education（教材术语库），S1。", "rp": "`attach increasing importance to`（L2·PC）；`enter a stage of`（L2·PC）。"}, {"term": "", "zh": "", "cn": "高校学生总数已接近 4700 万人，位居世界第一。", "en": "The total number of college students has approached 47 million, ranking first in the world.", "ptype": "真题", "cat": "真题A", "map": "高等教育", "set": "CET4 2023·06·S2", "src": "CET4 2023·06·S2", "cls": "Chapter 4", "tip": "断句:分句①②;核心=①;②→伴随状语(ranking first in the world)(CL-03);时锚:已→现在完成时;话题:补主语(→The total number of college students);文化:高校→colleges and universities；世界第一→rank(ing) first in the world", "ta": "补主语；分词状语（ranking…，连淑能 1993）；时态呼应（现在完成时，连淑能 1993）。", "te": "增补（the total number of）；数字表达（\"4700 万\"→47 million）；动词转译（\"位居\"→ranking）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`the total number of`（L2·PC）；`rank first in the world`（L2·PC）。"}, {"term": "", "zh": "", "cn": "随着我国经济的快速发展，人民生活水平不断提高，越来越多的人渴望接受高等教育。", "en": "With the rapid development of China's economy and the steady improvement of people's living standards, more and more people are eager to receive higher education.", "ptype": "真题", "cat": "真题A", "map": "高等教育", "set": "CET4 2023·06·S2", "src": "CET4 2023·06·S2", "cls": "Chapter 4", "tip": "断句:分句①②③;核心=③;①②→伴随状语(With…and…)；触发[随着]→With the rapid development of…|As…;时锚:一般现在时;话题:补主语(→more and more people);文化:人民生活水平→people's living standards；高等教育→S1 higher education", "ta": "伴随状语前置（with＋名词，连淑能 1993）；补主语。", "te": "名词化（\"发展\"→development；\"提高\"→improvement）；增补（steady）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"高等教育\"教材定译 higher education（教材术语库），S1。", "rp": "`with the rapid development of`（L2·PC）；`be eager to V`（L2·PC）。"}, {"term": "", "zh": "", "cn": "我国高校的数量和学科专业持续增加，招生人数逐年上升,教学质量也在不断改进，为更多年轻人创造了接受高等教育的机会。", "en": "The number of colleges and universities and academic programs in China has kept increasing, enrollment has risen year by year, and teaching quality has also been improving, creating opportunities for more young people to receive higher education.", "ptype": "真题", "cat": "真题A", "map": "高等教育", "set": "CET4 2023·06·S2", "src": "CET4 2023·06·S2", "cls": "Chapter 4", "tip": "断句:分句①②③④;核心=④|并列;①→the number…has kept increasing;②→enrollment has risen year by year;③→teaching quality has kept improving;④→伴随/结果(creating opportunities…)；时锚:持续/逐年/不断→现在完成进行时|现在完成时;话题:补主语(分别补 the number / enrollment / teaching quality);文化:学科专业→academic programs；招生人数→enrollment；教学质量→teaching quality；备注:[原卷如此]（\"逐年上升,教学质量\"处为半角逗号，照抄不改）", "ta": "补主语（三个分句各自补主语）；意合→形合（并列 and，连淑能 1993）；分词状语（creating…，连淑能 1993）；时态呼应（现在完成进行时，连淑能 1993）。", "te": "名词化（\"增加/上升/改进\"→kept increasing / has risen / kept improving）；增补（year by year / also）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"高等教育\"教材定译 higher education（教材术语库），S1。", "rp": "`keep V-ing`（L2·PC）；`year by year`（L2·PC）；`create opportunities for sb to V`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国越来越重视终身教育，发展继续教育是构建终身教育体系的有效途径。", "en": "China is attaching increasing importance to lifelong education, and developing continuing education is an effective way to build a lifelong education system.", "ptype": "真题", "cat": "真题A", "map": "终身教育/继续教育", "set": "CET4 2023·06·S3", "src": "CET4 2023·06·S3", "cls": "Chapter 4", "tip": "断句:分句①②;核心=②|并列;①→并列分句;话题:补主语(→China / developing continuing education);文化:终身教育→lifelong education；继续教育→continuing education；终身教育体系→lifelong education system", "ta": "补主语；动名词主语（\"发展继续教育\"→developing continuing education，连淑能 1993）；意合→形合（并列 and，连淑能 1993）。", "te": "增补（increasing）；词性转换（\"越来越重视\"→is attaching increasing importance to）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`attach importance to`（L2·PC）；`an effective way to V`（L2·PC）；`V-ing as subject`（L2·SB）→ 本句实例：developing continuing education is an effective way…。"}, {"term": "", "zh": "", "cn": "高校作为人才培养的基地，拥有先进的教学理念和优越的教学资源，理应成为继续教育的办学主体。", "en": "As bases for talent cultivation, colleges and universities have advanced teaching philosophies and superior teaching resources, and should therefore become the main providers of continuing education.", "ptype": "真题", "cat": "真题A", "map": "终身教育/继续教育", "set": "CET4 2023·06·S3", "src": "CET4 2023·06·S3", "cls": "Chapter 4", "tip": "断句:分句①②③;核心=③;①→状语/同位(As bases for talent cultivation);②→并列分句(have…);话题:补主语(→colleges and universities);文化:人才培养→talent cultivation；教学理念→teaching philosophies；教学资源→teaching resources；办学主体→main providers|principal providers", "ta": "补主语；状语前置（As bases…，连淑能 1993）；意合→形合（and should therefore，连淑能 1993）；修饰语后置（the main providers of…）。", "te": "增补（As / therefore）；词性转换（\"办学主体\"→main providers）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`as bases for`（L2·PC）；`teaching resources`（L2·PC）；`the main provider of`（L2·PC）。"}, {"term": "", "zh": "", "cn": "因此，近年来许多高校适应社会需求，加强与用人单位沟通，努力探索一条符合中国国情的继续教育发展新路，以使继续教育在国家发展战略中发挥更大的作用。", "en": "Therefore, in recent years many colleges and universities have adapted to social needs, strengthened communication with employers, and worked hard to explore a new path of continuing education development suited to China's national conditions, so that continuing education can play a greater role in the national development strategy.", "ptype": "真题", "cat": "真题A", "map": "终身教育/继续教育", "set": "CET4 2023·06·S3", "src": "CET4 2023·06·S3", "cls": "Chapter 4", "tip": "断句:分句①②③④;核心=③\"探索新路\";④→目的状语(so that…|in order to…);逻辑:因果→Therefore;时锚:近年来→现在完成时;话题:补主语(→many colleges and universities);触发[使]→enable|allow|so that…;文化:用人单位→employers；国情→national conditions；国家发展战略→national development strategy；发挥更大作用→play a greater role in", "ta": "补主语；目的状语化（so that…，连淑能 1993）；意合→形合（因果 Therefore，连淑能 1993）；修饰语后置（suited to China's national conditions）；时态呼应（现在完成时，连淑能 1993）。", "te": "增补（Therefore / in recent years）；词性转换（\"加强沟通\"→strengthened communication；\"适应\"→adapted to）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`adapt to`（L2·PC）；`play a greater role in`（L2·PC）；`so that … can V`（目的，L2·SB）→ 本句实例：…, so that continuing education can play a greater role in the national development strategy。"}, {"term": "", "zh": "", "cn": "中国有句老话：“一日为师，终身为父”。", "en": "There is an old saying in China: \"One who teaches you for a day is like a father for life.\"", "ptype": "真题", "cat": "真题A", "map": "尊师重教与教师节", "set": "CET4 2026·06·S1", "src": "CET4 2026·06·S1", "cls": "Chapter 4", "tip": "断句:单分句;核心=①;话题:There be 存在句(There is an old saying in China…);文化:一日为师终身为父→S4谚语通译(One who teaches you for a day is like a father for life)", "ta": "存在句（There be，连淑能 1993）；补主语（无主句→There be）。", "te": "增补（in China）；惯用等值（谚语义译，Molina & Albir 2002）。", "srcEn": "S2 · 整句无官方译文（整理编译）；谚语\"一日为师，终身为父\"无官方标准译法，标 S4 通译。", "rp": "`There is an old saying that / …: \"…\"`（L2·SB）→ 本句实例：There is an old saying in China: \"One who teaches you for a day is like a father for life.\"；`an old saying`（L2·PC）。"}, {"term": "", "zh": "", "cn": "在中国人的观念里，老师不仅传授知识，更教给学生做人的道理。", "en": "In the eyes of Chinese people, teachers not only impart knowledge but also teach students the principles of how to conduct themselves.", "ptype": "真题", "cat": "真题A", "map": "尊师重教与教师节", "set": "CET4 2026·06·S1", "src": "CET4 2026·06·S1", "cls": "Chapter 4", "tip": "断句:分句①②;核心=①;②→递进(but also);触发[不仅…更]→not only … but also …;话题:补主语(→teachers);文化:做人的道理→the principles of how to conduct oneself|the way to conduct oneself", "ta": "补主语；触发构式（not only…but also…，认知构式翻译观）；状语前置（In the eyes of…，连淑能 1993）。", "te": "惯用等值（\"在中国人的观念里\"→In the eyes of Chinese people；\"做人的道理\"→the principles of how to conduct themselves）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`not only … but also …`（L2·SB）→ 本句实例：teachers not only impart knowledge but also teach students…；`in the eyes of`（L2·PC）；`conduct oneself`（L2·PC）。"}, {"term": "", "zh": "", "cn": "在古代，学生初次见老师时要举行隆重的仪式，足见老师地位之高。", "en": "In ancient times, a grand ceremony was held when students first met their teachers, which shows how high the status of teachers was.", "ptype": "真题", "cat": "真题A", "map": "尊师重教与教师节", "set": "CET4 2026·06·S1", "src": "CET4 2026·06·S1", "cls": "Chapter 4", "tip": "断句:分句①②;核心=①;②→结果/评注(which shows…);时锚:在古代→一般过去时;话题:补主语(→students)｜受事→被动(a ceremony was held);文化:隆重仪式→a grand ceremony；地位之高→how high the status of teachers was", "ta": "受事→被动（a ceremony was held，CL-04）；时间状语前置（连淑能 1993）；意合→形合（which 非限制定从，连淑能 1993）；时态呼应（一般过去时，连淑能 1993）。", "te": "增补（grand / first）；词性转换（\"足见\"→which shows）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`was held`（L2·PC）；`which shows …`（L2·PC）。"}, {"term": "", "zh": "", "cn": "为弘扬尊师的优良传统，中国从1985年开始将每年的9月10日定为教师节。", "en": "To promote the fine tradition of respecting teachers, China has designated September 10 as Teachers' Day every year since 1985.", "ptype": "真题", "cat": "真题A", "map": "尊师重教与教师节", "set": "CET4 2026·06·S1", "src": "CET4 2026·06·S1", "cls": "Chapter 4", "tip": "断句:分句①/②;核心=②;①→目的状语(To promote…)(CL-07);时锚:从1985年开始→现在完成时(has designated since 1985)|一般过去时;话题:补主语(→China);文化:尊师→S1 honor teachers and value education(库)；优良传统→fine tradition；教师节→S1 Teachers' Day；备注:[原卷如此]（\"从1985年开始\"处年份前后无空格，照抄不改）", "ta": "补主语；目的状语前置（to promote…，连淑能 1993）；时态呼应（现在完成时，连淑能 1993）。", "te": "增补（To / every year）；动词转译（\"弘扬\"→promote；\"定（日期）为\"→designate… as…）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"尊师\"对应官方短语见库（honor teachers and value education，S1）；\"教师节\"为官方专名（Teachers' Day，S1）。", "rp": "`designate … as …`（L2·PC）；`To V …, 主句`（目的，CL-07）（L2·SB）→ 本句实例：To promote the fine tradition of respecting teachers, China has designated…。"}, {"term": "", "zh": "", "cn": "在这一天，学生以各种方式表达对老师的敬意。", "en": "On this day, students express their respect for teachers in various ways.", "ptype": "真题", "cat": "真题A", "map": "尊师重教与教师节", "set": "CET4 2026·06·S1", "src": "CET4 2026·06·S1", "cls": "Chapter 4", "tip": "断句:单分句;核心=①;话题:补主语(→students);逻辑:方式状语(in various ways);文化:敬意→respect|reverence", "ta": "补主语；时间状语前置（连淑能 1993）。", "te": "增补（their）；词性转换（\"以各种方式\"→in various ways）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`express one's respect for`（L2·PC）；`in various ways`（L2·PC）。"}, {"term": "", "zh": "", "cn": "尊师是中华民族的传统美德，在当今社会得到了发扬光大。", "en": "Respecting teachers is a traditional virtue of the Chinese nation, and it has been carried forward in today's society.", "ptype": "真题", "cat": "真题A", "map": "尊师重教与教师节", "set": "CET4 2026·06·S1", "src": "CET4 2026·06·S1", "cls": "Chapter 4", "tip": "断句:分句①②;核心=①;②→并列(and it has been…);时锚:得到了发扬光大→现在完成时;话题:动名词主语(→Respecting teachers)(CL-02);文化:尊师→S1 honor teachers and value education(库)；中华民族→S1 the Chinese nation(库)；传统美德→S1 traditional virtues(库)", "ta": "动名词主语（\"尊师\"→Respecting teachers，连淑能 1993）；意合→形合（并列 and it has been…，连淑能 1993）；时态呼应（现在完成时，连淑能 1993）。", "te": "惯用等值（\"发扬光大\"→carried forward）；增补（it）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"尊师\"见库（honor teachers and value education，S1）；\"中华民族\"见国新办白皮书（the Chinese nation，S1）；\"传统美德\"见库（traditional virtues，S1）。", "rp": "`a traditional virtue of`（L2·PC）；`carry forward`（L2·PC）；`V-ing as subject`（L2·SB）→ 本句实例：Respecting teachers is a traditional virtue…。"}, {"term": "", "zh": "", "cn": "中国父母往往过于关注孩子的学习，以至于不要他们帮忙做家务。", "en": "Chinese parents often focus too much on their children's studies, to the point that they do not let them help with housework.", "ptype": "真题", "cat": "真题A", "map": "父母对教育的关注", "set": "CET4 2015·12·S1", "src": "CET4 2015·12·S1", "cls": "Chapter 4", "tip": "断句:分句①②;核心=①;②→结果状语(so that…|to the point that…);触发[以至于]→so…that…|to the point that…;话题:补主语(→Chinese parents);文化:做家务→do housework", "ta": "补主语；意合→形合（结果 to the point that…，连淑能 1993）。", "te": "增补（too much）；动词转译（\"关注\"→focus on；\"帮忙做家务\"→help with housework）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`focus on`（L2·PC）；`help with`（L2·PC）；`to the point that …`（L2·SB）→ 本句实例：…, to the point that they do not let them help with housework。"}, {"term": "", "zh": "", "cn": "他们对孩子的首要要求就是努力学习，考得好，能上名牌大学。", "en": "Their most important requirement for their children is to study hard, get good grades, and be admitted to prestigious universities.", "ptype": "真题", "cat": "真题A", "map": "父母对教育的关注", "set": "CET4 2015·12·S1", "src": "CET4 2015·12·S1", "cls": "Chapter 4", "tip": "断句:单分句(含并列);核心=①;话题:补主语(→They);文化:首要要求→their top priority|primary requirement；名牌大学→prestigious universities(S4 通译)", "ta": "补主语；意合→形合（并列不定式 to study…, get…, and be admitted…，连淑能 1993）；受事→被动（be admitted，CL-04）。", "te": "词性转换（\"首要要求\"→most important requirement）；增补（their）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"名牌大学\"无白名单定译，标 S4。", "rp": "`get good grades`（L2·PC）；`be admitted to`（L2·PC）。"}, {"term": "", "zh": "", "cn": "他们相信这是为孩子好，因为在中国这样竞争激烈的社会里，只有成绩好才能保证前途光明。", "en": "They believe this is for their children's good, because in a society as competitive as China's, only good grades can guarantee a bright future.", "ptype": "真题", "cat": "真题A", "map": "父母对教育的关注", "set": "CET4 2015·12·S1", "src": "CET4 2015·12·S1", "cls": "Chapter 4", "tip": "断句:分句①②③;核心=①;②→原因状语(because…);③→条件/结果(only good grades can…);逻辑:因果→because;话题:补主语(→They);文化:竞争激烈→highly competitive；前途光明→a bright future", "ta": "补主语；意合→形合（因果 because，连淑能 1993）；状语前置（in a society…）。", "te": "增补（as competitive as）；惯用等值（\"为孩子好\"→for their children's good；\"成绩好\"→good grades）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`for one's good`（L2·PC）；`guarantee a bright future`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国父母还认为，如果孩子能在社会上取得大的成就，父母就会受到尊敬。", "en": "Chinese parents also believe that if their children can achieve great success in society, they will be respected.", "ptype": "真题", "cat": "真题A", "map": "父母对教育的关注", "set": "CET4 2015·12·S1", "src": "CET4 2015·12·S1", "cls": "Chapter 4", "tip": "断句:分句①②;核心=①;②→宾语从句(if…);逻辑:条件→if(CL-05);话题:补主语(→Chinese parents);受事→被动(父母会受到尊敬→will be respected);文化:取得大的成就→achieve great success in society", "ta": "补主语；条件状语从句（if…，连淑能 1993）；受事→被动（will be respected，CL-04）。", "te": "增补（also / great）；动词转译（\"取得成就\"→achieve success）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`believe that …`（L2·SB）→ 本句实例：Chinese parents also believe that if their children can achieve great success…；`achieve success in`（L2·PC）。"}, {"term": "", "zh": "", "cn": "因此，他们愿意牺牲自己的时间、爱好和兴趣，为孩子提供更好的条件。", "en": "Therefore, they are willing to sacrifice their own time, hobbies and interests to provide better conditions for their children.", "ptype": "真题", "cat": "真题A", "map": "父母对教育的关注", "set": "CET4 2015·12·S1", "src": "CET4 2015·12·S1", "cls": "Chapter 4", "tip": "断句:单分句;核心=①;逻辑:因果→Therefore;话题:补主语(→they);文化:牺牲→sacrifice；更好的条件→better conditions", "ta": "补主语；目的状语化（to provide…，连淑能 1993）；意合→形合（因果 Therefore，连淑能 1993）。", "te": "增补（their own / better）；动词转译（\"牺牲\"→sacrifice）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`be willing to V`（L2·PC）；`sacrifice … to V`（L2·PC）；`provide … for sb`（L2·PC）。"}], "examsB": [{"term": "", "zh": "", "cn": "中国将努力确保到 2015 年就业者接受过平均 13.3 年的教育。", "en": "China will work to ensure that by 2015 workers have received an average of 13.3 years of education.", "ptype": "真题", "cat": "真题B", "map": "教育制度与教育改革", "set": "CET6 2014·12·S3", "src": "CET6 2014·12·S3", "cls": "Chapter 4", "tip": "断句:单分句;核心=①;时锚:将/到2015年→一般将来时|将来完成时(will have received);话题:补主语(→China);触发[确保]→ensure that…；文化:就业者→workers|the employed；平均13.3年→an average of 13.3 years", "ta": "补主语；时态呼应（一般将来时＋完成体，连淑能 1993）。", "te": "增补（work to / an average of）；词性转换（\"接受过…教育\"→have received … education）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`work to V`（L2·PC）；`ensure that …`（L2·PC）；`an average of`（L2·PC）。"}, {"term": "", "zh": "", "cn": "如果这一目标得以实现，今后大部分进入劳动力市场的人都须获得大学文凭。", "en": "If this goal is achieved, most people entering the labor market in the future will need to obtain a college diploma.", "ptype": "真题", "cat": "真题B", "map": "教育制度与教育改革", "set": "CET6 2014·12·S3", "src": "CET6 2014·12·S3", "cls": "Chapter 4", "tip": "断句:分句①/②;核心=②;①→条件状语从句(If…)(CL-05 条件);话题:补主语(→most people);受事→被动(目标得以实现→is achieved);时锚:今后→一般将来时;文化:劳动力市场→the labor market；大学文凭→a college diploma", "ta": "条件状语从句前置（连淑能 1993）；补主语；受事→被动（is achieved，CL-04）；修饰语后置（entering the labor market）。", "te": "增补（in the future）；动词转译（\"获得\"→obtain）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`If …, 主句`（CL-05 条件）（L2·SB）→ 本句实例：If this goal is achieved, most people entering the labor market … will need to obtain…；`enter the labor market`（L2·PC）。"}, {"term": "", "zh": "", "cn": "在未来几年，中国将着力增加职业学院的招生人数；除了关注高等教育之外，还将寻找新的突破以确保教育制度更加公平。", "en": "In the coming years, China will focus on increasing enrollment in vocational colleges; apart from focusing on higher education, it will also seek new breakthroughs to ensure that the education system is more equitable.", "ptype": "真题", "cat": "真题B", "map": "教育制度与教育改革", "set": "CET6 2014·12·S3", "src": "CET6 2014·12·S3", "cls": "Chapter 4", "tip": "断句:分句①②③;核心=①|②并列;时锚:将→一般将来时;话题:补主语(→China);触发[确保]→ensure that…；文化:职业学院→vocational colleges；招生人数→enrollment；高等教育→S1 higher education；教育制度→the education system；新的突破→new breakthroughs", "ta": "补主语；时间状语前置（连淑能 1993）；意合→形合（分号并句 kept as parallel clauses，连淑能 1993）；目的状语化（to ensure…，连淑能 1993）。", "te": "增补（the coming / also）；词性转换（\"增加招生人数\"→increasing enrollment；\"寻找突破\"→seek breakthroughs）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"高等教育\"教材定译 higher education（教材术语库），S1。", "rp": "`focus on V-ing`（L2·PC）；`apart from V-ing`（L2·PC）；`seek new breakthroughs`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国正在努力最佳地利用教育资源，这样农村和欠发达地区将获得更多的支持。", "en": "China is working to make the best use of educational resources, so that rural and less developed areas will receive more support.", "ptype": "真题", "cat": "真题B", "map": "教育制度与教育改革", "set": "CET6 2014·12·S3", "src": "CET6 2014·12·S3", "cls": "Chapter 4", "tip": "断句:分句①②;核心=①;②→结果状语(so that…)|结果分句;时锚:正在→现在进行时;话题:补主语(→China);触发[这样]→so that…|so…；文化:教育资源→S3 educational resources(库)；欠发达地区→S1 less developed areas(库)；农村地区→S1 rural areas(库)", "ta": "补主语；结果状语化（so that…，连淑能 1993）；时态呼应（现在进行时，连淑能 1993）。", "te": "惯用等值（\"最佳地利用\"→make the best use of）；增补（so that / will）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"教育资源\"见库（educational resources，S3）；\"欠发达地区\"见中国政府网英文版（less developed areas，S1）；\"农村地区\"见教育部英文网（rural areas，S1）。", "rp": "`make the best use of`（L2·PC）；`so that … will V`（L2·SB）→ 本句实例：… make the best use of educational resources, so that rural and less developed areas will receive more support。"}, {"term": "", "zh": "", "cn": "教育部还决定改善欠发达地区学生的营养，并为外来务工人员的子女提供在城市接受教育的同等机会。", "en": "The Ministry of Education has also decided to improve the nutrition of students in less developed areas and provide the children of migrant workers with equal opportunities to receive education in cities.", "ptype": "真题", "cat": "真题B", "map": "教育制度与教育改革", "set": "CET6 2014·12·S3", "src": "CET6 2014·12·S3", "cls": "Chapter 4", "tip": "断句:分句①②;核心=①;②→并列(and provide…);时锚:一般过去时(decided)|现在完成时(has decided);话题:补主语(→The Ministry of Education);文化:教育部→the Ministry of Education；外来务工人员→migrant workers；同等机会→equal opportunities", "ta": "补主语；意合→形合（并列 and，连淑能 1993）；修饰语后置（of students in less developed areas；to receive education in cities）。", "te": "增补（also）；动词并列（\"改善…和为…提供…\"→improve… and provide…）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"教育部门\"见 China Daily（education authorities，S1）；本句\"教育部\"作 the Ministry of Education（专名通行译）。", "rp": "`decide to V`（L2·PC）；`provide sb with sth`（L2·PC）；`equal opportunities to V`（L2·PC）。"}, {"term": "", "zh": "", "cn": "注意：此部分试题请在答题卡 2 上作答。", "en": "Note: Please answer this part of the test on Answer Sheet 2.", "ptype": "真题", "cat": "真题B", "map": "教育制度与教育改革", "set": "CET6 2014·12·S3", "src": "CET6 2014·12·S3", "cls": "Chapter 4", "tip": "断句:单句(试卷指令，非语篇);核心=①;话题:无主句→祈使句(补 Please);备注:[试卷指令，非语篇内容，照抄保留]", "ta": "无主句→祈使句（补 Please，连淑能 1993）。", "te": "增补（Please）；词性转换（\"作答\"→answer）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`on Answer Sheet 2`（L2·PC）。"}, {"term": "", "zh": "", "cn": "在中国，父母总是竭力帮助孩子，甚至为孩手做重要决定，而不管孩子想要什么，因为他们相信这样做是为孩子好。", "en": "In China, parents always try their best to help their children and even make important decisions for them, regardless of what the children want, because they believe it is for the children's good.", "ptype": "真题", "cat": "真题B", "map": "中美父母教育观", "set": "CET6 2015·12·S1", "src": "CET6 2015·12·S1", "cls": "Chapter 4", "tip": "断句:分句①②③④;核心=①;②③→并列/让步(regardless of what…);④→原因状语(because…);逻辑:让步→regardless of|even if；因果→because;话题:补主语(→parents);文化:竭力帮助→try one's best to help；备注:[原卷如此]（\"孩手\"疑为\"孩子\"之误，照抄不改）", "ta": "补主语；意合→形合（让步 regardless of…＋因果 because…，连淑能 1993）；状语前置（In China）。", "te": "增补（always / even / their）；惯用等值（\"竭力\"→try their best；\"为孩子好\"→for the children's good）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"孩手\"为原卷笔误，照抄不改（通译按\"孩子\"处理）。", "rp": "`try one's best to V`（L2·PC）；`make decisions for sb`（L2·PC）；`regardless of`（L2·PC）。"}, {"term": "", "zh": "", "cn": "结果，孩子的成长和教育往往屈从于父母的意愿。", "en": "As a result, children's growth and education are often subject to their parents' will.", "ptype": "真题", "cat": "真题B", "map": "中美父母教育观", "set": "CET6 2015·12·S1", "src": "CET6 2015·12·S1", "cls": "Chapter 4", "tip": "断句:单分句;核心=①;逻辑:因果→As a result;话题:补主语(→children's growth and education);文化:屈从于…意愿→be subject to sb's will|give way to", "ta": "补主语；意合→形合（结果 As a result，连淑能 1993）；受事→被动语义（be subject to）。", "te": "增补（As a result / often）；惯用等值（\"屈从于…意愿\"→be subject to sb's will）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`as a result`（L2·PC）；`be subject to`（L2·PC）。"}, {"term": "", "zh": "", "cn": "如果父母决定为孩子报名参加一个课外班，以增加其被重点学校录取的机会，他们会坚持自己的决定，即使孩子根本不感兴趣。", "en": "If parents decide to sign their children up for an after-school class to increase their chances of admission to a key school, they will stick to their decision even if the children are not interested at all.", "ptype": "真题", "cat": "真题B", "map": "中美父母教育观", "set": "CET6 2015·12·S1", "src": "CET6 2015·12·S1", "cls": "Chapter 4", "tip": "断句:分句①②③;核心=②\"他们会坚持决定\";①→条件状语从句(If…);③→让步状语(even if…);逻辑:条件→if；让步→even if;话题:补主语(→they);文化:课外班→an after-school class|extracurricular class(库)；重点学校→key schools；录取→admission", "ta": "条件状语从句前置（连淑能 1993）；让步状语（even if…，连淑能 1993）；补主语。", "te": "增补（at all）；惯用等值（\"报名参加\"→sign … up for；\"坚持决定\"→stick to their decision）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"课外培训\"见库（after-school tutoring，S1，可互参）。", "rp": "`sign sb up for`（L2·PC）；`stick to`（L2·PC）；`even if …`（让步，L2·SB）→ 本句实例：…, they will stick to their decision even if the children are not interested at all。"}, {"term": "", "zh": "", "cn": "然而在美国，父母很可能会尊重孩子的意见，并在决策时更注重他们的意见。", "en": "In the United States, however, parents are likely to respect their children's opinions and pay more attention to them when making decisions.", "ptype": "真题", "cat": "真题B", "map": "中美父母教育观", "set": "CET6 2015·12·S1", "src": "CET6 2015·12·S1", "cls": "Chapter 4", "tip": "断句:分句①②;核心=①;②→并列(and pay more attention to…);逻辑:转折→However;话题:补主语(→parents);文化:尊重…意见→respect children's opinions；决策→make decisions", "ta": "补主语；意合→形合（转折 however，连淑能 1993）；状语前置（In the United States）。", "te": "增补（likely）；动词转译（\"尊重\"→respect；\"注重\"→pay more attention to）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`be likely to V`（L2·PC）；`pay attention to`（L2·PC）；`when V-ing`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国父母十分重视教育或许值得称赞。", "en": "That Chinese parents attach great importance to education is perhaps praiseworthy.", "ptype": "真题", "cat": "真题B", "map": "中美父母教育观", "set": "CET6 2015·12·S1", "src": "CET6 2015·12·S1", "cls": "Chapter 4", "tip": "断句:单分句;核心=①;话题:动名词/从句作主语(That Chinese parents attach… may be praiseworthy)|形式主语(It may be praiseworthy that…);文化:重视教育→attach great importance to education", "ta": "从句作主语（That…，连淑能 1993）；补主语。", "te": "增补（perhaps）；惯用等值（\"值得称赞\"→is praiseworthy）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"高度重视（+N）\"见 China Daily / 官方英文站（attach great importance to，S1）。", "rp": "`attach great importance to`（L2·PC）；`be praiseworthy`（L2·PC）。"}, {"term": "", "zh": "", "cn": "然而，他们应向美国父母学习在涉及教育时如何平衡父母与子女间的关系。", "en": "However, they should learn from American parents how to balance the relationship between parents and children when it comes to education.", "ptype": "真题", "cat": "真题B", "map": "中美父母教育观", "set": "CET6 2015·12·S1", "src": "CET6 2015·12·S1", "cls": "Chapter 4", "tip": "断句:单分句;核心=①;逻辑:转折→However;话题:补主语(→they);文化:平衡…关系→balance the relationship between…；涉及教育→when it comes to education", "ta": "补主语；意合→形合（转折 However，连淑能 1993）。", "te": "增补（how to）；惯用等值（\"在涉及教育时\"→when it comes to education）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`learn from`（L2·PC）；`balance the relationship between … and …`（L2·PC）；`when it comes to`（L2·PC）。"}, {"term": "", "zh": "", "cn": "注意：此部分试题请在答题卡 2 上作答。", "en": "Note: Please answer this part of the test on Answer Sheet 2.", "ptype": "真题", "cat": "真题B", "map": "中美父母教育观", "set": "CET6 2015·12·S1", "src": "CET6 2015·12·S1", "cls": "Chapter 4", "tip": "断句:单句(试卷指令，非语篇);核心=①;话题:无主句→祈使句(补 Please);备注:[试卷指令，非语篇内容，照抄保留]", "ta": "无主句→祈使句（补 Please，连淑能 1993）。", "te": "增补（Please）；词性转换（\"作答\"→answer）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`on Answer Sheet 2`（L2·PC）。"}], "vocabHF": [], "exercises": []}